INSERT INTO `news_detail` VALUES (103, 3728, 6, '科技与数字服务', 'Robo.ai宣布任命阿联酋科技高管出任新并购AI数据处理公司Neurovia首席技术官', '', '5月13日消息，阿联酋纳斯达克上市公司Robo.ai Inc.宣布，其新近收购的子公司Neurovia AI董事会已正式任命Mansoor Ali Khan担任首席技术官。Mansoor将全面领导专有边缘处理与数据压缩技术的研发，并统筹推进相关产品在AI产业领域客户中的适配与应用落地。（界面）', 'https://36kr.com/newsflashes/3807128790474500?f=rss', 0, '', '{\"summary\": \"本文披露海外AI企业并购后的高管任命动态，为出海科技企业了解中东AI行业发展提供参考\", \"abstract\": \"本文发布阿联酋纳斯达克上市公司Robo.ai Inc.的最新人事动态。Robo.ai新近收购了AI数据处理公司Neurovia，Neurovia董事会正式任命阿联酋科技高管Mansoor Ali Khan担任首席技术官。新任CTO将全面领导专有边缘处理与数据压缩技术的研发工作。其还将统筹推进相关技术产品在AI产业客户中的适配与落地应用。\", \"keywords\": [\"AI数据处理\", \"企业并购\", \"高管任命\", \"边缘处理\", \"数据压缩\", \"阿联酋\", \"纳斯达克\"], \"policy_risk\": {\"market_risk\": \"未提及\", \"policy_compliance\": \"未提及\"}, \"topic_cluster\": \"海外市场洞察\", \"industry_category\": \"科技与数字服务\"}', '', '{\"url\": \"https://36kr.com/newsflashes/3807128790474500?f=rss\", \"title\": \"Robo.ai宣布任命阿联酋科技高管出任新并购AI数据处理公司Neurovia首席技术官\", \"source\": \"https://36kr.com/feed\", \"content\": \"5月13日消息，阿联酋纳斯达克上市公司Robo.ai Inc.宣布，其新近收购的子公司Neurovia AI董事会已正式任命Mansoor Ali Khan担任首席技术官。Mansoor将全面领导专有边缘处理与数据压缩技术的研发，并统筹推进相关产品在AI产业领域客户中的适配与应用落地。（界面）\", \"is_policy\": 0, \"origin_msg\": {\"link\": \"https://36kr.com/newsflashes/3807128790474500?f=rss\", \"links\": [{\"rel\": \"alternate\", \"href\": \"https://36kr.com/newsflashes/3807128790474500?f=rss\", \"type\": \"text/html\"}], \"title\": \"Robo.ai宣布任命阿联酋科技高管出任新并购AI数据处理公司Neurovia首席技术官\", \"source\": {\"title\": \"36氪\"}, \"summary\": \"5月13日消息，阿联酋纳斯达克上市公司Robo.ai Inc.宣布，其新近收购的子公司Neurovia AI董事会已正式任命Mansoor Ali Khan担任首席技术官。Mansoor将全面领导专有边缘处理与数据压缩技术的研发，并统筹推进相关产品在AI产业领域客户中的适配与应用落地。（界面）\", \"published\": \"2026-05-13 10:51:40  +0800\", \"title_detail\": {\"base\": \"https://36kr.com/feed\", \"type\": \"text/plain\", \"value\": \"Robo.ai宣布任命阿联酋科技高管出任新并购AI数据处理公司Neurovia首席技术官\", \"language\": null}, \"summary_detail\": {\"base\": \"https://36kr.com/feed\", \"type\": \"text/html\", \"value\": \"5月13日消息，阿联酋纳斯达克上市公司Robo.ai Inc.宣布，其新近收购的子公司Neurovia 