INSERT INTO `news_detail` VALUES (104, 3732, 7, '消费与零售', '泡泡玛特：国际油价及航运市场波动较大，对海外业务毛利率造成影响', '', '泡泡玛特管理层在5月13日举行的电话会上表示，近期国际油价及航运市场波动幅度较大，尤其国际航运���油价格走高，公司头程海运费、燃油附加费、仓储成本均有所增加，这些因素会对海外业务毛利率造成影响。（证券时报）', 'https://36kr.com/newsflashes/3807119085002245?f=rss', 0, '', '{\"summary\": \"本文披露泡泡玛特海外业务受国际油价及航运波动影响毛利率承压，可为出海消费企业成本管控提供参考\", \"abstract\": \"本文源自证券时报对泡泡玛特管理层电话会议内容的报道。泡泡玛特管理层在5月13日的电话会上表示，近期国际油价及航运市场波动幅度较大，航运燃油价格走高推高了公司头程海运费、燃油附加费与仓储成本。成本上涨最终对泡泡玛特的海外业务毛利率造成了不利影响。\", \"keywords\": [\"泡泡玛特\", \"海外业务\", \"毛利率\", \"国际油价\", \"航运波动\", \"海运成本\"], \"policy_risk\": {\"market_risk\": \"国际油价及航运市场波动较大，航运燃油价格走高，推高出海企业头程海运费、燃油附加费及仓储成本，会挤压海外业务毛利率\", \"policy_compliance\": \"未提及\"}, \"topic_cluster\": \"供应链物流\", \"industry_category\": \"消费与零售\"}', '', '{\"url\": \"https://36kr.com/newsflashes/3807119085002245?f=rss\", \"title\": \"泡泡玛特：国际油价及航运市场波动较大，对海外业务毛利率造成影响\", \"source\": \"https://36kr.com/feed\", \"content\": \"泡泡玛特管理层在5月13日举行的电话会上表示，近期国际油价及航运市场波动幅度较大，尤其国际航运���油价格走高，公司头程海运费、燃油附加费、仓储成本均有所增加，这些因素会对海外业务毛利率造成影响。（证券时报）\", \"is_policy\": 0, \"origin_msg\": {\"link\": \"https://36kr.com/newsflashes/3807119085002245?f=rss\", \"links\": [{\"rel\": \"alternate\", \"href\": \"https://36kr.com/newsflashes/3807119085002245?f=rss\", \"type\": \"text/html\"}], \"title\": \"泡泡玛特：国际油价及航运市场波动较大，对海外业务毛利率造成影响\", \"source\": {\"title\": \"36氪\"}, \"summary\": \"泡泡玛特管理层在5月13日举行的电话会上表示，近期国际油价及航运市场波动幅度较大，尤其国际航运���油价格走高，公司头程海运费、燃油附加费、仓储成本均有所增加，这些因素会对海外业务毛利率造成影响。（证券时报）\", \"published\": \"2026-05-13 10:41:48  +0800\", \"title_detail\": {\"base\": \"https://36kr.com/feed\", \"type\": \"text/plain\", \"value\": \"泡泡玛特：国际油价及航运市场波动较大，对海外业务毛利率造成影响\", \"language\": null}, \"summary_detail\": {\"base\": \"https://36kr.com/feed\", \"type\": \"text/html\", \"value\": \"泡泡玛特管理层在5月13日举行的电话会上表示，近期国际油价及航运市场波动幅度较大，尤其国际航运���油价格走高，公司头程海运费、燃油附加费、仓储成本均有所增加，这些因素会对海外业务毛利率造成影响。（证券时报）\", \"language\": null}, \"published_parsed\": [2026, 5, 13, 2, 41, 48, 2, 133, 0]}, \"published_at\": \"2026-05-13 10:41:48\", \"ai_jso