INSERT INTO `news_detail` VALUES (105, 3746, 20, '其他', '前4个月粤港澳大湾区内地9市外贸连续保持两位数增长', '', '据海关统计，今年前4个月，粤港澳大湾区内地9市进出口3.37万亿元，同比增长18.4%，占全国进出口总值的比重较去年同期提升0.6个百分点至20.7%，对全国增长的贡献度达24.9%。其中，出口2万亿元，增长11.4%；进口1.37亿元，增长30.4%。（央视新闻）', 'https://36kr.com/newsflashes/3807074673680130?f=rss', 0, '', '{\"summary\": \"本文公布粤港澳大湾区内地9市前4个月外贸增长数据，帮助出海主体把握区域外贸发展态势。\", \"abstract\": \"本文引用海关统计数据，公布今年前4个月粤港澳大湾区内地9市的外贸进出口情况。该区域前4个月进出口总额达3.37万亿元，同比增长18.4%，占全国进出口总值比重提升至20.7%，对全国外贸增长贡献度达24.9%。其中出口2万亿元，同比增长11.4%，进口1.37万亿元，同比增长30.4%。数据表明大湾区外贸连续保持两位数的良好增长势头。\", \"keywords\": [\"粤港澳大湾区\", \"外贸增长\", \"进出口\", \"出口\", \"进口\", \"全国外贸\"], \"policy_risk\": {\"market_risk\": \"未提及\", \"policy_compliance\": \"未提及\"}, \"topic_cluster\": \"海外市场洞察\", \"industry_category\": \"其他\"}', '', '{\"url\": \"https://36kr.com/newsflashes/3807074673680130?f=rss\", \"title\": \"前4个月粤港澳大湾区内地9市外贸连续保持两位数增长\", \"source\": \"https://36kr.com/feed\", \"content\": \"据海关统计，今年前4个月，粤港澳大湾区内地9市进出口3.37万亿元，同比增长18.4%，占全国进出口总值的比重较去年同期提升0.6个百分点至20.7%，对全国增长的贡献度达24.9%。其中，出口2万亿元，增长11.4%；进口1.37亿元，增长30.4%。（央视新闻）\", \"is_policy\": 0, \"origin_msg\": {\"link\": \"https://36kr.com/newsflashes/3807074673680130?f=rss\", \"links\": [{\"rel\": \"alternate\", \"href\": \"https://36kr.com/newsflashes/3807074673680130?f=rss\", \"type\": \"text/html\"}], \"title\": \"前4个月粤港澳大湾区内地9市外贸连续保持两位数增长\", \"source\": {\"title\": \"36氪\"}, \"summary\": \"据海关统计，今年前4个月，粤港澳大湾区内地9市进出口3.37万亿元，同比增长18.4%，占全国进出口总值的比重较去年同期提升0.6个百分点至20.7%，对全国增长的贡献度达24.9%。其中，出口2万亿元，增长11.4%；进口1.37亿元，增长30.4%。（央视新闻）\", \"published\": \"2026-05-13 09:56:37  +0800\", \"title_detail\": {\"base\": \"https://36kr.com/feed\", \"type\": \"text/plain\", \"value\": \"前4个月粤港澳大湾区内地9市外贸连续保持两位数增长\", \"language\": null}, \"summary_detail\": {\"base\": \"https://36kr.com/feed\", \"type\": \"text/html\", \"value\": \"据海关统计，今年前4个月，粤港澳大湾区内地9市进出口3.37万亿元，同比增长18.4%，占全国进出口总值的比重较去年同期提升0.6个百分点至20.7%，对全国增长的贡献度达24.9%。其中，出口2万亿元，增长11.4%；进口1.37亿元，增长30.4%。（央视新闻）\", \"language\": null}, \"published_parsed\": [2026, 5, 13, 