INSERT INTO `news_detail` VALUES (106, 3748, 9, '内容与社交', 'TikTok在印尼、美国、日本三国官宣生活服务品牌TikTok GO', '', '36氪获悉，TikTok近日宣布，正式在美国和日本推出生活服务品牌TikTok GO。据了解，TikTok GO去年在印尼的餐饮订单量增长超过20倍，在日本和美国分别提供了8万和36万��旅行体验服务。', 'https://36kr.com/newsflashes/3807067123556099?f=rss', 0, '', '{\"summary\": \"本文披露TikTok在美日推出生活服务品牌TikTok GO，帮助出海从业者了解短视频平台海外本地生活扩张动态\", \"abstract\": \"TikTok近日正式在美国、日本推出生活服务品牌TikTok GO。该品牌此前已落地印尼市场，过去一年印尼地区餐饮订单量增长超20倍。TikTok GO目前在日本和美国分别提供8万和36万份旅行体验服务。这一动作体现了TikTok加速拓展海外本地生活服务赛道的布局节奏。\", \"keywords\": [\"TikTok GO\", \"TikTok\", \"生活服务\", \"海外扩张\", \"本地生活\", \"印尼\", \"美国\", \"日本\"], \"policy_risk\": {\"market_risk\": \"未提及\", \"policy_compliance\": \"未提及\"}, \"topic_cluster\": \"海外市场洞察\", \"industry_category\": \"内容与社交\"}', '', '{\"url\": \"https://36kr.com/newsflashes/3807067123556099?f=rss\", \"title\": \"TikTok在印尼、美国、日本三国官宣生活服务品牌TikTok GO\", \"source\": \"https://36kr.com/feed\", \"content\": \"36氪获悉，TikTok近日宣布，正式在美国和日本推出生活服务品牌TikTok GO。据了解，TikTok GO去年在印尼的餐饮订单量增长超过20倍，在日本和美国分别提供了8万和36万��旅行体验服务。\", \"is_policy\": 0, \"origin_msg\": {\"link\": \"https://36kr.com/newsflashes/3807067123556099?f=rss\", \"links\": [{\"rel\": \"alternate\", \"href\": \"https://36kr.com/newsflashes/3807067123556099?f=rss\", \"type\": \"text/html\"}], \"title\": \"TikTok在印尼、美国、日本三国官宣生活服务品牌TikTok GO\", \"source\": {\"title\": \"36氪\"}, \"summary\": \"36氪获悉，TikTok近日宣布，正式在美国和日本推出生活服务品牌TikTok GO。据了解，TikTok GO去年在印尼的餐饮订单量增长超过20倍，在日本和美国分别提供了8万和36万��旅行体验服务。\", \"published\": \"2026-05-13 09:48:56  +0800\", \"title_detail\": {\"base\": \"https://36kr.com/feed\", \"type\": \"text/plain\", \"value\": \"TikTok在印尼、美国、日本三国官宣生活服务品牌TikTok GO\", \"language\": null}, \"summary_detail\": {\"base\": \"https://36kr.com/feed\", \"type\": \"text/html\", \"value\": \"36氪获悉，TikTok近日宣布，正式在美国和日本推出生活服务品牌TikTok GO。据了解，TikTok GO去年在印尼的餐饮订单量增长超过20倍，在日本和美国分别提供了8万和36万��旅行体验服务。\", \"language\": null}, \"published_parsed\": [2026, 5, 13, 1, 48, 56, 2, 133, 0]}, \"published_at\": \"2026-05-13 09:48:56\", \"ai_json_output