INSERT INTO `news_detail` VALUES (147, 4112, 17, '文化与IP出海', '山西文旅IP亮相香港国际授权展 达成多项合作意向', '', '<a href=\"http://baijiahao.baidu.com/s?id=1863980068933458668\"><img src=\"http://t1.baidu.com/it/u=http%3A%2F%2Ft11.baidu.com%2Fit%2Fu%3D900774873%2C295544847%26fm%3D30%26app%3D106%26f%3DJPEG%3Fw%3D312%26h%3D208%26s%3DFA92098D081929C83491CD0F03007080&amp;fm=30\"></a><br><br>', 'http://baijiahao.baidu.com/s?id=1863980068933458668', 0, '', '{\"summary\": \"本文报道山西文旅IP参展香港国际授权展达成多项合作，为国内文旅IP出海拓展市场提供参考\", \"abstract\": \"本文报道山西文旅IP亮相香港国际授权展。此次参展是山西文旅IP探索出海合作、拓展海外市场的实践。本次参展最终达成了多项合作意向。为国内地方文旅IP出海发展提供了有益参考\", \"keywords\": [\"文旅IP\", \"香港国际授权展\", \"IP出海\", \"合作意向\"], \"policy_risk\": {\"market_risk\": \"未提及\", \"policy_compliance\": \"未提及\"}, \"topic_cluster\": \"文化与IP出海\", \"industry_category\": \"文化与IP出海\"}', '', '{\"url\": \"http://baijiahao.baidu.com/s?id=1863980068933458668\", \"title\": \"山西文旅IP亮相香港国际授权展 达成多项合作意向\", \"source\": \"http://news.baidu.com/n?cmd=1&class=gangaotai&tn=rss\", \"content\": \"<a href=\\\"http://baijiahao.baidu.com/s?id=1863980068933458668\\\"><img src=\\\"http://t1.baidu.com/it/u=http%3A%2F%2Ft11.baidu.com%2Fit%2Fu%3D900774873%2C295544847%26fm%3D30%26app%3D106%26f%3DJPEG%3Fw%3D312%26h%3D208%26s%3DFA92098D081929C83491CD0F03007080&amp;fm=30\\\"></a><br><br>\", \"is_policy\": 0, \"origin_msg\": {\"link\": \"http://baijiahao.baidu.com/s?id=1863980068933458668\", \"links\": [{\"rel\": \"alternate\", \"href\": \"http://baijiahao.baidu.com/s?id=1863980068933458668\", \"type\": \"text/html\"}], \"title\": \"山西文旅IP亮相香港国际授权展 达成多项合作意向\", \"author\": \"\", \"source\": {}, \"authors\": [{}], \"summary\": \"<a href=\\\"http://baijiahao.baidu.com/s?id=1863980068933458668\\\" target=\\\"_blank\\\"><img border=\\\"0\\\" src=\\\"http://t1.baidu.com/it/u=http%3A%2F%2Ft11.baidu.com%2Fit%2Fu%3D900774873%2C295544847%26fm%3D30%26app%3D106%26f%3DJPEG%3Fw%3D312%26h%3D208%26s%3DFA92098D081929C83491CD0F03007080&amp;fm=30\\\" /></a><br /><br />\", \"published\": \"2026-05-13T04:03:36.000Z\", \"title_detail\": {\"base\": \"https://news.baidu.com/n?cmd=1&class=gangaotai&tn=rss\", \"type\": \"text/plain\", \"value\": \"山西文旅IP亮相香港国际授权展 达成多项合作意向\", \"language\": null}, \"summary_detail\": {\"base\": \"https://news.baidu.com/n?cmd=1&class=gangaotai&tn=rss\", \"type\": \"text/html\", \"value\": \"<a href=\\\"http://baijiahao.baidu.com/s?id=1863980068933458668\\\" target=\\\"_blank\\\"><img border=\\\"0\\\" src=\\\"http://t1.baidu.com/it/u=http%3A%2F%2Ft11.baidu.com%2Fit%2Fu%3D900774873%2C295544847%26fm%3D30%26app%3D106%26f%3DJPEG%3Fw%3D312%26h%3D208%26s%3DFA92098D081929C83491CD0F03007080&amp;fm=30\\\" /></a><br /><br />\", \"language\": null}, \"published_parsed\": [2026, 5, 13, 4, 3, 36, 2, 133, 0]}, \"published_at\": \"2026-05-13 04:03:36\", \"ai_json_output\": \"\"}', '百度首页\n登录\n搜索\n复制\n山西文旅IP亮相香港国际授权展 达成多项合作意向\n中国新闻网\n2026-05-01 18:03\n北京中新网信息科技有限公司官方账号\n关注\n中新网太原5月1日电 (刘小红)近日，山西文旅IP亮相2026中国文化和旅游IP授权系列活动暨香港国际授权展，完成晋港企业对接洽谈，推动三晋文化走向海外市场。\n山西文旅IP亮相2026中国文化和旅游IP授权系列活动暨香港国际授权展。山西省文化和旅游厅供图\n此次参展，山西组织近20家企业入驻“中国内地馆”，以“五千年文明看山西”为主题打造特色山西馆，展出绣品、剪纸、漆盒、砂器、葡萄酒、小米醋等文旅展品，覆盖文创、非遗、特色食品等类别，集中展现了山西从文物资源到文创产品的创新转化成果，让千年文化以可触可感的方式走进大众视野。\n展会期间，晋港企业深度对接、成果丰硕。山西文物博物产业集团通过展会对接香港各界，推动山西壁画、古建等文化资源的IP授权与商业转化，探索文化传承与文物事业反哺的新路径；戎子酒庄携全系列葡萄酒产品参展，与全球客商达成初步合作意向，依托香港国际化渠道拓展海外市场。\n山西组织近20家企业入驻“中国内地馆”，以“五千年文明看山西”为主题打造特色山西馆。山西省文化和旅游厅供图\n山西同步举办参展企业(香港)对接洽谈会，搭建合作平台推动晋港文旅资源融合。深耕国货领域多年的裕华国货有限公司总经理(零售)孙伯阳表示，山西非遗产品的创新设计与IP赋能，为弘扬中国文化搭建了优质渠道，期待未来深化合作，让更多优秀国货走进香港、走向世界。中新青年企业家总商会创会主席梁文杰指出，香港的金融、贸易与创意产业优势，将助力山西文旅文创产品进入国际市场。\n此次参展打通山西文化IP对外传播渠道，推动三晋优秀传统文化在国际交流中落地转化，实现文旅资源海外推广目标。(完)\n举报/反馈\n0\n0\n收藏\n分享\n微信好友\n新浪微博\n复制链接\n扫码分享至微信\n设为首页\n© Baidu\n使用百度前必读\n京ICP证030173号\n京公网安备11000002000001号', NULL, '2026-05-13 12:22:32');
INSERT INTO `news_detail` VALUES (148, 4133, 11, '服务与基建', '假期跨境游火爆！深港“双向奔赴”再升温', '', '<a href=\"http://baijiahao.baidu.com/s?id=1864177294964379576\"><img src=\"http://t1.baidu.com/it/u=http%3A%2F%2Ft12.baidu.com%2Fit%2Fu%3D3670561808%2C295728557%26fm%3D30%26app%3D106%26f%3DJPEG%3Fw%3D312%26h%3D208%26s%3D92A061A75421C8FE5688E02003006051&amp;fm=30\"></a><br><br>', 'http://baijiahao.baidu.com/s?id=1864177294964379576', 0, '', '{\"summary\": \"本文提及假期深港跨境游升温，可供布局港澳跨境旅游的相关出海企业参考市场动态\", \"abstract\": \"本文标题为《假期跨境游火爆！深港“双向奔赴”再升温》，仅保留跳转链接与占位图片，未提供完整正文内容，无法获取更多出海相关的细节信息。\", \"keywords\": [\"跨境游\", \"深港旅游\", \"假期出游\"], \"policy_risk\": {\"market_risk\": \"未提及\", \"policy_compliance\": \"未提及\"}, \"topic_cluster\": \"服务与基建\", \"industry_category\": \"服务与基建\"}', '', '{\"url\": \"http://baijiahao.baidu.com/s?id=1864177294964379576\", \"title\": \"假期跨境游火爆！深港“双向奔赴”再升温\", \"source\": \"http://news.baidu.com/n?cmd=1&class=gangaotai&tn=rss\", \"content\": \"<a href=\\\"http://baijiahao.baidu.com/s?id=1864177294964379576\\\"><img src=\\\"http://t1.baidu.com/it/u=http%3A%2F%2Ft12.baidu.com%2Fit%2Fu%3D3670561808%2C295728557%26fm%3D30%26app%3D106%26f%3DJPEG%3Fw%3D312%26h%3D208%26s%3D92A061A75421C8FE5688E02003006051&amp;fm=30\\\"></a><br><br>\", \"is_policy\": 0, \"origin_msg\": {\"link\": \"http://baijiahao.baidu.com/s?id=1864177294964379576\", \"links\": [{\"rel\": \"alternate\", \"href\": \"http://baijiahao.baidu.com/s?id=1864177294964379576\", \"type\": \"text/html\"}], \"title\": \"假期跨境游火爆！深港“双向奔赴”再升温\", \"author\": \"\", \"source\": {}, \"authors\": [{}], \"summary\": \"<a href=\\\"http://baijiahao.baidu.com/s?id=1864177294964379576\\\" target=\\\"_blank\\\"><img border=\\\"0\\\" src=\\\"http://t1.baidu.com/it/u=http%3A%2F%2Ft12.baidu.com%2Fit%2Fu%3D3670561808%2C295728557%26fm%3D30%26app%3D106%26f%3DJPEG%3Fw%3D312%26h%3D208%26s%3D92A061A75421C8FE5688E02003006051&amp;fm=30\\\" /></a><br /><br />\", \"published\": \"2026-05-13T04:03:37.000Z\", \"title_detail\": {\"base\": \"https://news.baidu.com/n?cmd=1&class=gangaotai&tn=rss\", \"type\": \"text/plain\", \"value\": \"假期跨境游火爆！深港“双向奔赴”再升温\", \"language\": null}, \"summary_detail\": {\"base\": \"https://news.baidu.com/n?cmd=1&class=gangaotai&tn=rss\", \"type\": \"text/html\", \"value\": \"<a href=\\\"http://baijiahao.baidu.com/s?id=1864177294964379576\\\" target=\\\"_blank\\\"><img border=\\\"0\\\" src=\\\"http://t1.baidu.com/it/u=http%3A%2F%2Ft12.baidu.com%2Fit%2Fu%3D3670561808%2C295728557%26fm%3D30%26app%3D106%26f%3DJPEG%3Fw%3D312%26h%3D208%26s%3D92A061A75421C8FE5688E02003006051&amp;fm=30\\\" /></a><br /><br />\", \"language\": null}, \"published_parsed\": [2026, 5, 13, 4, 3, 37, 2, 133, 0]}, \"published_at\": \"2026-05-13 04:03:37\", \"ai_json_output\": \"\"}', '百度首页\n登录\n搜索\n复制\n假期跨境游火爆！深港“双向奔赴”再升温\n深圳特区报\n2026-05-03 19:11\n深圳特区报社\n关注\n“五一”假期，深港口岸迎来出入境双向客流高峰，香港居民赴内地消费热潮持续涌动，内地居民赴港观演打卡热情高涨。多项数据刷新单日出入境客流纪录，成为粤港澳大湾区深度融合、人员往来火热的鲜活缩影。\n假期期间，深港两地居民“双向奔赴”，热闹非凡。深圳各大商圈、口岸枢纽人流如织，香港入境旅客往来不断，商贸休闲、餐饮文旅等持续攀升。与此同时，众多内地居民纷纷经各口岸赴港观演，探亲访友、漫步维港、打卡文化地标。从口岸到商圈、从街头到景区，跨境出行、探亲访友、休闲消费需求集中释放，既有力推动深港文旅经济稳步升温，也在频繁往来中增进文化认同与情感交融，绘就出两地深度融合、协同发展的生动画卷。\n作为深港跨境通行的核心枢纽，皇岗、福田口岸始终保持高效顺畅运行。5月2日晚间，受草蜢红馆演唱会、太极乐队演唱会及金圣圭香港演唱会等多场大型演艺活动散场影响，大批歌迷及跨境旅客经皇岗口岸入境返程。\n据深圳边检总站统计，5月2日，皇岗边检站查验出入境人员逾33.7万人次，创历史新高；其中出境人员逾17.3万人次，刷新全站历史峰值；福田口岸查验出入境旅客逾26.8万人次，其中出境旅客逾13.6万人次，均创口岸开通以来纪录。\n面对假期客流高峰，边检部门依托“数字孪生平台”与视频巡控系统的深度融合，实现对分时流量和高峰时段的精准研判，并调整查验通道，提升通关效率与应急响应速度。\n今年是APEC会议举办之年，双向客流新高既彰显出深港两地经贸人文交流日益紧密，更折射出粤港澳大湾区融合发展动能持续强劲。随着通关便利化水平不断提升、免签“朋友圈”相关政策红利持续释放，深港口岸正成为人员高效往来、经贸深度融通、民心紧密相连的重要纽带。\n（受访方供图）\n（作者：深圳特区报&读特记者 吴梓欣 通讯员 黄俊生 罗惟婷 黄千佩）\n举报/反馈\n0\n0\n收藏\n分享\n微信好友\n新浪微博\n复制链接\n扫码分享至微信\n设为首页\n© Baidu\n使用百度前必读\n京ICP证030173号\n京公网安备11000002000001号', NULL, '2026-05-13 12:23:02');
INSERT INTO `news_detail` VALUES (149, 4311, 11, '服务与基建', 'AI+供应链：大模型与智能决策如何重构供应链全链路| 2026AI Partner·北京亦庄AI+产业大会', '', 'AI究竟如何为产业创造价值？见证AI从“热点”转化为“生产力”的关键一跃。\n\n今天的顺丰已经用AI调度着中国三分之一的航空货运。从百万人的协同、二十万辆车的调度，到每天五千万票件的动态路由——物流供应链的复杂度，正是AI落地的最佳试验田。一个超大规模网络如何用大模型、Agent和运筹算法，将“24小时达”从承诺变成日常，并将这份能力输送给更多中国企业。\n\n以下为顺丰集团数智供应链解决方案事业群高级副总裁 唐恺 演讲内容，经36氪整理编辑：\n\n<img src=\"https://img.36krcdn.com/hsossms/20260522/v2_a74464ffd6d84a209c5e0d4a24b00e52@6381723_oswg129508oswg1000oswg666_img_jpg?x-oss-process=image/quality,q_100/format,jpg/interlace,1\">\n\n唐恺丨顺丰集团数智供应链解决方案事业群高级副总裁\n\n各位来宾下午好，很高兴来到亦庄这样的场合跟大家分享物流供应链AI的应用。\n\n开始之前跟大家讲一下供应链，从智能化视角或者数字化视角来看供应链，需要把供应链做一个抽象或者分层，统一来讲供应链是无从下手的，会用要素、链路、网络这三个层级去看整个供应链的协同以及看供应链的数字化进展和智能化进展，供应链基础要素我们叫作人车货场，所有供应链的动作和执行都是跟要素串联相关的，要素的调动形成链路，链路交织形成网络，单纯从顺丰来看，我们讲其中一个点顺丰自身在供应链领域的超大规模性，人车货场，人，在顺丰体系协同的员工超过一百万人的协同规模，整个车辆自有车辆超过20万辆，更大是中国的航空空运网络，中国有240架全货机，110架是在顺丰手上，更密集的航空网络是整个辅仓运力网络，客机辅仓也是运货的，辅仓运力三分之一是在顺丰的手上，也就是说今天中国头上飞过三架飞机，就有一架飞机运的是顺丰的货。\n\n在要素密集程度下，我们还要叠加链路复杂性，链路对于快递来说是收转运派，对于供应链叫作采购供应链、生产供应链、渠道供应链、消费供应链、售后供应链。收转运派四个环节听起来简单，整个运作过程中有120个环节串联起来，形成整个收转运派的链路，整个链路执行复杂度是非常高的，所有的链路交织形成大的网络，在大的网络中顺丰要做的一个事情，所有在上面的资源和链路需要做整个基于数字网络的智能调度和智能协同。今天顺丰为什么能够给客户做24小时达或者48小时达的承诺，因为所有链路调动过程中都是基于自主能力，我们叫作智能化、自主化做动态调度。\n\n动态调度，今天一个票件从北京发到深圳，该上什么飞机，用哪个小哥取件、哪个小哥派件，经过哪个中转场，静态路由是定好的，但是飞机会晚点，小哥会生病，汽车开在路上可能会抛锚，所有的节点都可能出现问题，顺丰一天处理五千万的票件，有50%的票件是要启动动态路由的，比如一个车在路径上不该停止的地方停止过长时间，系统会自动识别是否属于不正常状态，经过确认，比如他在高速上抛锚，整个系统会自动调度附近的空时车辆去做时效挽救，整个链路在24小时范围内要保证链路不出问题，基于大网络的资源协同和资源调度，必须由智能和数字化的事情来完成，不可能由人工完成。大模型是在2022年年底ChatGPT出来以后才火的，2016年我们就开始大规模地部署我们基于运筹算法、传统机器学习和强化学习智能化能力，是2025年唯一进入弗兰兹·厄德曼决赛的亚洲公司，这个奖项是运筹学界里最高奖项，代表了我们在整个运筹里的能力，传统机器学习能力，在整个大模型的时代开始大面积转向大模型的能力。\n\n在这样的复杂网络里，顺丰做的事情基于所有全链路端到端全量数字化全栈自研，从底层的能力，我们甚至有自己的地图部门，虽然可以使用高德导航、百度导航，但顺丰需要工业级导航，因此我们有自己的地图部门。我们导航的细度（远高于普通导航），你用百度只能导到小区，用丰图进到小区里可以知道怎么走，每个楼层都有哪些公司、住户，所有信息我们通过小哥每天的派送自动更新和采集，我们叫作全栈自研的能力。\n\n从2023年开始大面积构建大模型的网络和体系，现在我们大概有两个大的垂域模型，一个是丰遇大模型，这个是多模态大模型，主要是为内部相关业务使用的，包括网络调度、各种各样的细节应用。另外一个丰知大模型，面向行业推出的物流垂域大模型。今天整个模型应用，大家比较有感知的话题，比如Agent，我们从底层模型开放，再到Agent平台，再到市场，再到自构建的能力，在内部做了所有的转化，今天顺丰内部大概会有五千多个Agent是实时跑的，这里面有两百多个是官方Agent，比如智能网络调度Agent，运筹优化Agent，所有的Agent是200个是官方的，剩下4800个都是各个业务部门非技术人员，基于Agent平台在建的小Agent，大概每天消耗八百亿个token数量。\n\n基于我们对整个行业，对自身的数字化和智能化能力，我们把相应的能力，在要素复杂度、链路复杂度、网络复杂度上顺丰都有现成可考的模板。对于大多数公司，在要素、链路、网络复杂度是不如顺丰的，我们把能力进行抽象，形成几个大方面的能力，第一个垂域大模型，我们叫作物流决策大模型，基于丰知的产品体系来做。另外一个物流端到端的操作系统，我们叫作丰智云，还有面向合作伙伴LAAS物流开放平台，我们希望提供基于咨询、AI、数字化多链路服务，赋能整个行业，让每一家企业、行业、产业供应链都能变得更加聪明。\n\n丰知，我们通过丰知把我们所有传统的物流软件叠加Agent能力，稍微理解供应链就知道，供应链有一个仓储管理软件，我们希望提供给客户是直接带Agent能力的软件功能。这其中是差异可以这么理解，如果大家买一辆传统的汽车，你需要再买一个工具来使用它。如果大家买的是自动驾驶汽车，你是直接买服务的，工具需要人的使用变成服务，而自动驾驶汽车直接提供的是运人或者运货的服务，不需要有能力转化的，垂域应用领域我们直接提供Agent能力，我们通过丰知的AgentOS帮助企业快速建立我刚才讲的顺丰内部能力。还有一个Agent Studio，业务语义中心帮助大家在所有的数字化基础上去建构知识图谱模型，以前你的企业数据是给系统用的，但是我们通过语义中心，大模型自动建模，使得所有数据能够被Agent直接调用，通过Agent Studio在你已有的数字化平台上直接建构Agent应用，支持大面积使用。我们有两个底层应用做支撑，第一个丰知Code，用来做整个软件大规模定制的，把定制成本的边际成本降得非常低。还有一个丰知Evolver，大模型生成小模型，今天基于供应链的诊断和咨询，不是方法论先导，模型先导，我们希望通过数据，POC快速做咨询验证、供应链诊断，这部分会涉及到大量的模型生成，如何打开产能瓶颈，通过丰知Evolver、大模型自动生成小模型，大量生成定制化小模型，同时能够使模型调优时间大幅下降。\n\n这部分是大模型——物流决策大模型，做三个事，第一个供应链预测、供应链优化、供应链分析。\n\n供应链预测，我们做的是通过大模型的模态泛化，解决预测里很难做的几个特殊场景。比如新品预测和芯片预测，缺乏历史数据，以前的模型很难算得准，通过大模型做自动化咨询建模，以前是单SQ建模，现在是QA通道类的集群建模，使得整个数据关联性和数据补充性能够做得更好，在全球最大的咖啡连锁企业做的数据验证，大概能够提升5个点的准确率，是之前的模型完全没有办法做到的。\n\n另外一个供应链优化，我们通过大模型重写了以前运筹的经典模型，比如路径优化和专项优化场景，你用transformer架构重写这部分模型以后，运算时间提升一万倍左右，原来你做一个串点路径优化需要分钟级运算时间，现在可以下降到毫秒级，0.05秒就可以计算完成，资源消耗是之前的50分之一，以前要50个CPU来算，今天1个GPU就可以算完。\n\n另外一个分析的能力，这一部分分析的能力，大模型结合小模型，通过供应链智能体的方式来做这个事情，智能体在整个行业特别火的时候，是2025年3月份，2B应用我们很早就意识到，整个2B要解决模型黑盒的问题，解决模型高效和准确的问题，必须通过智能体的方式来做，2024年8月份在行业里推出供应链智能体综合应用的能力。\n\n在智能化之前，所有企业都逃不开的数字化第一步，模型再强，数据准确性、实时性、可靠性不够，肯定是得不到好的结果，在智能化之前，端到端数字化，我们通过丰智云链模型体系来做整个客户基于要素、链路的全链路数字化。\n\n最后讲一个案例，全球最大的咖啡连锁企业在中国有七千多家门店，2019年就开始帮他做智慧门店的系统，我们帮他做的是基于门店系统做门店级别的销售预测和补货预测，我们已经做了六年，我们用大模型帮他做传统模型的迭代。\n\n国际知名美妆巨头，在中国全渠道销售预测是我们帮他做的，为什么在中国的全渠道销售预测要我们做？因为中国渠道复杂度远超于任何一个单体国家，他的连锁企业在中国落地的实践经验比美国更加先进，之前跟美国的CIO聊，中国业务资本结构发生变化，中国主体收购了他在中国的业务，这一块暂时没有往前走。\n\n中国供应链深度、广度、复杂度是全球无二的，我们服务MNC企业的时候，我们在中国落地的供应链实践，就是全球最佳的供应链实践，在很多跨国企业客户上得到了验证，以前供应链数字化最佳实践叫作copy to china，今天做的事情是copy from china，在奢侈品行业，全球第一个智慧门店是长沙LV，我们帮他做的。工业制造领域伊顿供应链中台是在中国生产完成以后，再向亚太地区推的，我们给雀巢做高阶生产排程的POC，在中国不好用，需要中国的本土能力来做本土化实验，在数字化供应链叠加整个技术变革，叠加到AI能力越境的时候，我们看到更多的是中国有很大的机会窗口来做数字供应链全球最佳实践。\n\n我们也提出了从底层到上层所有能力，包括咨询诊断和顶规开始，再到大模型AI应用能力，以及到端到端的数字化能力，再结合到每个行业不同解决方案细化的能力，配合到供应链从采购供应链、渠道供应链、销售供应链、售后供应链全链路服务，今天我们希望跟更多的中国企业一起创造更多全球最佳供应链实践。\n\n谢谢大家。', 'https://36kr.com/p/3820107133555077?f=rss', 0, '', '{\"summary\": \"本文分享顺丰AI大模型重构供应链全链路的落地实践，可为出海企业搭建智能供应链提供成熟解决方案参考。\", \"abstract\": \"这是顺丰集团高管在AI+产业大会上分享AI重构物流供应链全链路的实践经验。顺丰依托自身超大规模供应链网络，早早布局智能化能力，目前已自研两个物流垂域大模型，构建数千个智能Agent实现网络动态调度。顺丰将自身智能化能力抽象为标准化产品，面向全行业开放赋能。中国供应链的深度与复杂度全球独有，当前中国供应链数字化实践已经从\\\"copy to china\\\"转为\\\"copy from china\\\"，有望诞生更多全球最佳实践。\", \"keywords\": [\"AI大模型\", \"供应链重构\", \"智能调度\", \"物流垂域大模型\", \"动态路由\", \"供应链数字化\", \"Agent\"], \"policy_risk\": {\"market_risk\": \"未提及\", \"policy_compliance\": \"未提及\"}, \"topic_cluster\": \"供应链物流\", \"industry_category\": \"服务与基建\"}', '', '{\"url\": \"https://36kr.com/p/3820107133555077?f=rss\", \"title\": \"AI+供应链：大模型与智能决策如何重构供应链全链路| 2026AI Partner·北京亦庄AI+产业大会\", \"source\": \"https://36kr.com/feed\", \"content\": \"AI究竟如何为产业创造价值？见证AI从“热点”转化为“生产力”的关键一跃。\\n\\n今天的顺丰已经用AI调度着中国三分之一的航空货运。从百万人的协同、二十万辆车的调度，到每天五千万票件的动态路由——物流供应链的复杂度，正是AI落地的最佳试验田。一个超大规模网络如何用大模型、Agent和运筹算法，将“24小时达”从承诺变成日常，并将这份能力输送给更多中国企业。\\n\\n以下为顺丰集团数智供应链解决方案事业群高级副总裁 唐恺 演讲内容，经36氪整理编辑：\\n\\n<img src=\\\"https://img.36krcdn.com/hsossms/20260522/v2_a74464ffd6d84a209c5e0d4a24b00e52@6381723_oswg129508oswg1000oswg666_img_jpg?x-oss-process=image/quality,q_100/format,jpg/interlace,1\\\">\\n\\n唐恺丨顺丰集团数智供应链解决方案事业群高级副总裁\\n\\n各位来宾下午好，很高兴来到亦庄这样的场合跟大家分享物流供应链AI的应用。\\n\\n开始之前跟大家讲一下供应链，从智能化视角或者数字化视角来看供应链，需要把供应链做一个抽象或者分层，统一来讲供应链是无从下手的，会用要素、链路、网络这三个层级去看整个供应链的协同以及看供应链的数字化进展和智能化进展，供应链基础要素我们叫作人车货场，所有供应链的动作和执行都是跟要素串联相关的，要素的调动形成链路，链路交织形成网络，单纯从顺丰来看，我们讲其中一个点顺丰自身在供应链领域的超大规模性，人车货场，人，在顺丰体系协同的员工超过一百万人的协同规模，整个车辆自有车辆超过20万辆，更大是中国的航空空运网络，中国有240架全货机，110架是在顺丰手上，更密集的航空网络是整个辅仓运力网络，客机辅仓也是运货的，辅仓运力三分之一是在顺丰的手上，也就是说今天中国头上飞过三架飞机，就有一架飞机运的是顺丰的货。\\n\\n在要素密集程度下，我们还要叠加链路复杂性，链路对于快递来说是收转运派，对于供应链叫作采购供应链、生产供应链、渠道供应链、消费供应链、售后供应链。收转运派四个环节听起来简单，整个运作过程中有120个环节串联起来，形成整个收转运派的链路，整个链路执行复杂度是非常高的，所有的链路交织形成大的网络，在大的网络中顺丰要做的一个事情，所有在上面的资源和链路需要做整个基于数字网络的智能调度和智能协同。今天顺丰为什么能够给客户做24小时达或者48小时达的承诺，因为所有链路调动过程中都是基于自主能力，我们叫作智能化、自主化做动态调度。\\n\\n动态调度，今天一个票件从北京发到深圳，该上什么飞机，用哪个小哥取件、哪个小哥派件，经过哪个中转场，静态路由是定好的，但是飞机会晚点，小哥会生病，汽车开在路上可能会抛锚，所有的节点都可能出现问题，顺丰一天处理五千万的票件，有50%的票件是要启动动态路由的，比如一个车在路径上不该停止的地方停止过长时间，系统会自动识别是否属于不正常状态，经过确认，比如他在高速上抛锚，整个系统会自动调度附近的空时车辆去做时效挽救，整个链路在24小时范围内要保证链路不出问题，基于大网络的资源协同和资源调度，必须由智能和数字化的事情来完成，不可能由人工完成。大模型是在2022年年底ChatGPT出来以后才火的，2016年我们就开始大规模地部署我们基于运筹算法、传统机器学习和强化学习智能化能力，是2025年唯一进入弗兰兹·厄德曼决赛的亚洲公司，这个奖项是运筹学界里最高奖项，代表了我们在整个运筹里的能力，传统机器学习能力，在整个大模型的时代开始大面积转向大模型的能力。\\n\\n在这样的复杂网络里，顺丰做的事情基于所有全链路端到端全量数字化全栈自研，从底层的能力，我们甚至有自己的地图部门，虽然可以使用高德导航、百度导航，但顺丰需要工业级导航，因此我们有自己的地图部门。我们导航的细度（远高于普通导航），你用百度只能导到小区，用丰图进到小区里可以知道怎么走，每个楼层都有哪些公司、住户，所有信息我们通过小哥每天的派送自动更新和采集，我们叫作全栈自研的能力。\\n\\n从2023年开始大面积构建大模型的网络和体系，现在我们大概有两个大的垂域模型，一个是丰遇大模型，这个是多模态大模型，主要是为内部相关业务使用的，包括网络调度、各种各样的细节应用。另外一个丰知大模型，面向行业推出的物流垂域大模型。今天整个模型应用，大家比较有感知的话题，比如Agent，我们从底层模型开放，再到Agent平台，再到市场，再到自构建的能力，在内部做了所有的转化，今天顺丰内部大概会有五千多个Agent是实时跑的，这里面有两百多个是官方Agent，比如智能网络调度Agent，运筹优化Agent，所有的Agent是200个是官方的，剩下4800个都是各个业务部门非技术人员，基于Agent平台在建的小Agent，大概每天消耗八百亿个token数量。\\n\\n基于我们对整个行业，对自身的数字化和智能化能力，我们把相应的能力，在要素复杂度、链路复杂度、网络复杂度上顺丰都有现成可考的模板。对于大多数公司，在要素、链路、网络复杂度是不如顺丰的，我们把能力进行抽象，形成几个大方面的能力，第一个垂域大模型，我们叫作物流决策大模型，基于丰知的产品体系来做。另外一个物流端到端的操作系统，我们叫作丰智云，还有面向合作伙伴LAAS物流开放平台，我们希望提供基于咨询、AI、数字化多链路服务，赋能整个行业，让每一家企业、行业、产业供应链都能变得更加聪明。\\n\\n丰知，我们通过丰知把我们所有传统的物流软件叠加Agent能力，稍微理解供应链就知道，供应链有一个仓储管理软件，我们希望提供给客户是直接带Agent能力的软件功能。这其中是差异可以这么理解，如果大家买一辆传统的汽车，你需要再买一个工具来使用它。如果大家买的是自动驾驶汽车，你是直接买服务的，工具需要人的使用变成服务，而自动驾驶汽车直接提供的是运人或者运货的服务，不需要有能力转化的，垂域应用领域我们直接提供Agent能力，我们通过丰知的AgentOS帮助企业快速建立我刚才讲的顺丰内部能力。还有一个Agent Studio，业务语义中心帮助大家在所有的数字化基础上去建构知识图谱模型，以前你的企业数据是给系统用的，但是我们通过语义中心，大模型自动建模，使得所有数据能够被Agent直接调用，通过Agent Studio在你已有的数字化平台上直接建构Agent应用，支持大面积使用。我们有两个底层应用做支撑，第一个丰知Code，用来做整个软件大规模定制的，把定制成本的边际成本降得非常低。还有一个丰知Evolver，大模型生成小模型，今天基于供应链的诊断和咨询，不是方法论先导，模型先导，我们希望通过数据，POC快速做咨询验证、供应链诊断，这部分会涉及到大量的模型生成，如何打开产能瓶颈，通过丰知Evolver、大模型自动生成小模型，大量生成定制化小模型，同时能够使模型调优时间大幅下降。\\n\\n这部分是大模型——物流决策大模型，做三个事，第一个供应链预测、供应链优化、供应链分析。\\n\\n供应链预测，我们做的是通过大模型的模态泛化，解决预测里很难做的几个特殊场景。比如新品预测和芯片预测，缺乏历史数据，以前的模型很难算得准，通过大模型做自动化咨询建模，以前是单SQ建模，现在是QA通道类的集群建模，使得整个数据关联性和数据补充性能够做得更好，在全球最大的咖啡连锁企业做的数据验证，大概能够提升5个点的准确率，是之前的模型完全没有办法做到的。\\n\\n另外一个供应链优化，我们通过大模型重写了以前运筹的经典模型，比如路径优化和专项优化场景，你用transformer架构重写这部分模型以后，运算时间提升一万倍左右，原来你做一个串点路径优化需要分钟级运算时间，现在可以下降到毫秒级，0.05秒就可以计算完成，资源消耗是之前的50分之一，以前要50个CPU来算，今天1个GPU就可以算完。\\n\\n另外一个分析的能力，这一部分分析的能力，大模型结合小模型，通过供应链智能体的方式来做这个事情，智能体在整个行业特别火的时候，是2025年3月份，2B应用我们很早就意识到，整个2B要解决模型黑盒的问题，解决模型高效和准确的问题，必须通过智能体的方式来做，2024年8月份在行业里推出供应链智能体综合应用的能力。\\n\\n在智能化之前，所有企业都逃不开的数字化第一步，模型再强，数据准确性、实时性、可靠性不够，肯定是得不到好的结果，在智能化之前，端到端数字化，我们通过丰智云链模型体系来做整个客户基于要素、链路的全链路数字化。\\n\\n最后讲一个案例，全球最大的咖啡连锁企业在中国有七千多家门店，2019年就开始帮他做智慧门店的系统，我们帮他做的是基于门店系统做门店级别的销售预测和补货预测，我们已经做了六年，我们用大模型帮他做传统模型的迭代。\\n\\n国际知名美妆巨头，在中国全渠道销售预测是我们帮他做的，为什么在中国的全渠道销售预测要我们做？因为中国渠道复杂度远超于任何一个单体国家，他的连锁企业在中国落地的实践经验比美国更加先进，之前跟美国的CIO聊，中国业务资本结构发生变化，中国主体收购了他在中国的业务，这一块暂时没有往前走。\\n\\n中国供应链深度、广度、复杂度是全球无二的，我们服务MNC企业的时候，我们在中国落地的供应链实践，就是全球最佳的供应链实践，在很多跨国企业客户上得到了验证，以前供应链数字化最佳实践叫作copy to china，今天做的事情是copy from china，在奢侈品行业，全球第一个智慧门店是长沙LV，我们帮他做的。工业制造领域伊顿供应链中台是在中国生产完成以后，再向亚太地区推的，我们给雀巢做高阶生产排程的POC，在中国不好用，需要中国的本土能力来做本土化实验，在数字化供应链叠加整个技术变革，叠加到AI能力越境的时候，我们看到更多的是中国有很大的机会窗口来做数字供应链全球最佳实践。\\n\\n我们也提出了从底层到上层所有能力，包括咨询诊断和顶规开始，再到大模型AI应用能力，以及到端到端的数字化能力，再结合到每个行业不同解决方案细化的能力，配合到供应链从采购供应链、渠道供应链、销售供应链、售后供应链全链路服务，今天我们希望跟更多的中国企业一起创造更多全球最佳供应链实践。\\n\\n谢谢大家。\", \"is_policy\": 0, \"origin_msg\": {\"link\": \"https://36kr.com/p/3820107133555077?f=rss\", \"links\": [{\"rel\": \"alternate\", \"href\": \"https://36kr.com/p/3820107133555077?f=rss\", \"type\": \"text/html\"}], \"title\": \"AI+供应链：大模型与智能决策如何重构供应链全链路| 2026AI Partner·北京亦庄AI+产业大会\", \"source\": {\"title\": \"36氪\"}, \"summary\": \"<p>AI究竟如何为产业创造价值？见证AI从“热点”转化为“生产力”的关键一跃。</p>\\n  <p>今天的顺丰已经用AI调度着中国三分之一的航空货运。从百万人的协同、二十万辆车的调度，到每天五千万票件的动态路由——物流供应链的复杂度，正是AI落地的最佳试验田。一个超大规模网络如何用大模型、Agent和运筹算法，将“24小时达”从承诺变成日常，并将这份能力输送给更多中国企业。</p>\\n  <p>以下为顺丰集团数智供应链解决方案事业群高级副总裁 唐恺 演讲内容，经36氪整理编辑：</p>\\n  <p class=\\\"image-wrapper\\\"><img src=\\\"https://img.36krcdn.com/hsossms/20260522/v2_a74464ffd6d84a209c5e0d4a24b00e52@6381723_oswg129508oswg1000oswg666_img_jpg?x-oss-process=image/quality,q_100/format,jpg/interlace,1\\\" /></p>\\n  <p>唐恺丨顺丰集团数智供应链解决方案事业群高级副总裁</p>\\n  <p>各位来宾下午好，很高兴来到亦庄这样的场合跟大家分享物流供应链AI的应用。</p>\\n  <p>开始之前跟大家讲一下供应链，从智能化视角或者数字化视角来看供应链，需要把供应链做一个抽象或者分层，统一来讲供应链是无从下手的，会用要素、链路、网络这三个层级去看整个供应链的协同以及看供应链的数字化进展和智能化进展，供应链基础要素我们叫作人车货场，所有供应链的动作和执行都是跟要素串联相关的，要素的调动形成链路，链路交织形成网络，单纯从顺丰来看，我们讲其中一个点顺丰自身在供应链领域的超大规模性，人车货场，人，在顺丰体系协同的员工超过一百万人的协同规模，整个车辆自有车辆超过20万辆，更大是中国的航空空运网络，中国有240架全货机，110架是在顺丰手上，更密集的航空网络是整个辅仓运力网络，客机辅仓也是运货的，辅仓运力三分之一是在顺丰的手上，也就是说今天中国头上飞过三架飞机，就有一架飞机运的是顺丰的货。</p>\\n  <p>在要素密集程度下，我们还要叠加链路复杂性，链路对于快递来说是收转运派，对于供应链叫作采购供应链、生产供应链、渠道供应链、消费供应链、售后供应链。收转运派四个环节听起来简单，整个运作过程中有120个环节串联起来，形成整个收转运派的链路，整个链路执行复杂度是非常高的，所有的链路交织形成大的网络，在大的网络中顺丰要做的一个事情，所有在上面的资源和链路需要做整个基于数字网络的智能调度和智能协同。今天顺丰为什么能够给客户做24小时达或者48小时达的承诺，因为所有链路调动过程中都是基于自主能力，我们叫作智能化、自主化做动态调度。</p>\\n  <p>动态调度，今天一个票件从北京发到深圳，该上什么飞机，用哪个小哥取件、哪个小哥派件，经过哪个中转场，静态路由是定好的，但是飞机会晚点，小哥会生病，汽车开在路上可能会抛锚，所有的节点都可能出现问题，顺丰一天处理五千万的票件，有50%的票件是要启动动态路由的，比如一个车在路径上不该停止的地方停止过长时间，系统会自动识别是否属于不正常状态，经过确认，比如他在高速上抛锚，整个系统会自动调度附近的空时车辆去做时效挽救，整个链路在24小时范围内要保证链路不出问题，基于大网络的资源协同和资源调度，必须由智能和数字化的事情来完成，不可能由人工完成。大模型是在2022年年底ChatGPT出来以后才火的，2016年我们就开始大规模地部署我们基于运筹算法、传统机器学习和强化学习智能化能力，是2025年唯一进入弗兰兹·厄德曼决赛的亚洲公司，这个奖项是运筹学界里最高奖项，代表了我们在整个运筹里的能力，传统机器学习能力，在整个大模型的时代开始大面积转向大模型的能力。</p>\\n  <p>在这样的复杂网络里，顺丰做的事情基于所有全链路端到端全量数字化全栈自研，从底层的能力，我们甚至有自己的地图部门，虽然可以使用高德导航、百度导航，但顺丰需要工业级导航，因此我们有自己的地图部门。我们导航的细度（远高于普通导航），你用百度只能导到小区，用丰图进到小区里可以知道怎么走，每个楼层都有哪些公司、住户，所有信息我们通过小哥每天的派送自动更新和采集，我们叫作全栈自研的能力。</p>\\n  <p>从2023年开始大面积构建大模型的网络和体系，现在我们大概有两个大的垂域模型，一个是丰遇大模型，这个是多模态大模型，主要是为内部相关业务使用的，包括网络调度、各种各样的细节应用。另外一个丰知大模型，面向行业推出的物流垂域大模型。今天整个模型应用，大家比较有感知的话题，比如Agent，我们从底层模型开放，再到Agent平台，再到市场，再到自构建的能力，在内部做了所有的转化，今天顺丰内部大概会有五千多个Agent是实时跑的，这里面有两百多个是官方Agent，比如智能网络调度Agent，运筹优化Agent，所有的Agent是200个是官方的，剩下4800个都是各个业务部门非技术人员，基于Agent平台在建的小Agent，大概每天消耗八百亿个token数量。</p>\\n  <p>基于我们对整个行业，对自身的数字化和智能化能力，我们把相应的能力，在要素复杂度、链路复杂度、网络复杂度上顺丰都有现成可考的模板。对于大多数公司，在要素、链路、网络复杂度是不如顺丰的，我们把能力进行抽象，形成几个大方面的能力，第一个垂域大模型，我们叫作物流决策大模型，基于丰知的产品体系来做。另外一个物流端到端的操作系统，我们叫作丰智云，还有面向合作伙伴LAAS物流开放平台，我们希望提供基于咨询、AI、数字化多链路服务，赋能整个行业，让每一家企业、行业、产业供应链都能变得更加聪明。</p>\\n  <p>丰知，我们通过丰知把我们所有传统的物流软件叠加Agent能力，稍微理解供应链就知道，供应链有一个仓储管理软件，我们希望提供给客户是直接带Agent能力的软件功能。这其中是差异可以这么理解，如果大家买一辆传统的汽车，你需要再买一个工具来使用它。如果大家买的是自动驾驶汽车，你是直接买服务的，工具需要人的使用变成服务，而自动驾驶汽车直接提供的是运人或者运货的服务，不需要有能力转化的，垂域应用领域我们直接提供Agent能力，我们通过丰知的AgentOS帮助企业快速建立我刚才讲的顺丰内部能力。还有一个Agent Studio，业务语义中心帮助大家在所有的数字化基础上去建构知识图谱模型，以前你的企业数据是给系统用的，但是我们通过语义中心，大模型自动建模，使得所有数据能够被Agent直接调用，通过Agent Studio在你已有的数字化平台上直接建构Agent应用，支持大面积使用。我们有两个底层应用做支撑，第一个丰知Code，用来做整个软件大规模定制的，把定制成本的边际成本降得非常低。还有一个丰知Evolver，大模型生成小模型，今天基于供应链的诊断和咨询，不是方法论先导，模型先导，我们希望通过数据，POC快速做咨询验证、供应链诊断，这部分会涉及到大量的模型生成，如何打开产能瓶颈，通过丰知Evolver、大模型自动生成小模型，大量生成定制化小模型，同时能够使模型调优时间大幅下降。</p>\\n  <p>这部分是大模型——物流决策大模型，做三个事，第一个供应链预测、供应链优化、供应链分析。</p>\\n  <p>供应链预测，我们做的是通过大模型的模态泛化，解决预测里很难做的几个特殊场景。比如新品预测和芯片预测，缺乏历史数据，以前的模型很难算得准，通过大模型做自动化咨询建模，以前是单SQ建模，现在是QA通道类的集群建模，使得整个数据关联性和数据补充性能够做得更好，在全球最大的咖啡连锁企业做的数据验证，大概能够提升5个点的准确率，是之前的模型完全没有办法做到的。</p>\\n  <p>另外一个供应链优化，我们通过大模型重写了以前运筹的经典模型，比如路径优化和专项优化场景，你用transformer架构重写这部分模型以后，运算时间提升一万倍左右，原来你做一个串点路径优化需要分钟级运算时间，现在可以下降到毫秒级，0.05秒就可以计算完成，资源消耗是之前的50分之一，以前要50个CPU来算，今天1个GPU就可以算完。</p>\\n  <p>另外一个分析的能力，这一部分分析的能力，大模型结合小模型，通过供应链智能体的方式来做这个事情，智能体在整个行业特别火的时候，是2025年3月份，2B应用我们很早就意识到，整个2B要解决模型黑盒的问题，解决模型高效和准确的问题，必须通过智能体的方式来做，2024年8月份在行业里推出供应链智能体综合应用的能力。</p>\\n  <p>在智能化之前，所有企业都逃不开的数字化第一步，模型再强，数据准确性、实时性、可靠性不够，肯定是得不到好的结果，在智能化之前，端到端数字化，我们通过丰智云链模型体系来做整个客户基于要素、链路的全链路数字化。</p>\\n  <p>最后讲一个案例，全球最大的咖啡连锁企业在中国有七千多家门店，2019年就开始帮他做智慧门店的系统，我们帮他做的是基于门店系统做门店级别的销售预测和补货预测，我们已经做了六年，我们用大模型帮他做传统模型的迭代。</p>\\n  <p>国际知名美妆巨头，在中国全渠道销售预测是我们帮他做的，为什么在中国的全渠道销售预测要我们做？因为中国渠道复杂度远超于任何一个单体国家，他的连锁企业在中国落地的实践经验比美国更加先进，之前跟美国的CIO聊，中国业务资本结构发生变化，中国主体收购了他在中国的业务，这一块暂时没有往前走。</p>\\n  <p>中国供应链深度、广度、复杂度是全球无二的，我们服务MNC企业的时候，我们在中国落地的供应链实践，就是全球最佳的供应链实践，在很多跨国企业客户上得到了验证，以前供应链数字化最佳实践叫作copy to china，今天做的事情是copy from china，在奢侈品行业，全球第一个智慧门店是长沙LV，我们帮他做的。工业制造领域伊顿供应链中台是在中国生产完成以后，再向亚太地区推的，我们给雀巢做高阶生产排程的POC，在中国不好用，需要中国的本土能力来做本土化实验，在数字化供应链叠加整个技术变革，叠加到AI能力越境的时候，我们看到更多的是中国有很大的机会窗口来做数字供应链全球最佳实践。</p>\\n  <p>我们也提出了从底层到上层所有能力，包括咨询诊断和顶规开始，再到大模型AI应用能力，以及到端到端的数字化能力，再结合到每个行业不同解决方案细化的能力，配合到供应链从采购供应链、渠道供应链、销售供应链、售后供应链全链路服务，今天我们希望跟更多的中国企业一起创造更多全球最佳供应链实践。</p>\\n  <p>谢谢大家。</p>\", \"published\": \"2026-05-22 14:54:18  +0800\", \"title_detail\": {\"base\": \"https://36kr.com/feed\", \"type\": \"text/plain\", \"value\": \"AI+供应链：大模型与智能决策如何重构供应链全链路| 2026AI Partner·北京亦庄AI+产业大会\", \"language\": null}, \"summary_detail\": {\"base\": \"https://36kr.com/feed\", \"type\": \"text/html\", \"value\": \"<p>AI究竟如何为产业创造价值？见证AI从“热点”转化为“生产力”的关键一跃。</p>\\n  <p>今天的顺丰已经用AI调度着中国三分之一的航空货运。从百万人的协同、二十万辆车的调度，到每天五千万票件的动态路由——物流供应链的复杂度，正是AI落地的最佳试验田。一个超大规模网络如何用大模型、Agent和运筹算法，将“24小时达”从承诺变成日常，并将这份能力输送给更多中国企业。</p>\\n  <p>以下为顺丰集团数智供应链解决方案事业群高级副总裁 唐恺 演讲内容，经36氪整理编辑：</p>\\n  <p class=\\\"image-wrapper\\\"><img src=\\\"https://img.36krcdn.com/hsossms/20260522/v2_a74464ffd6d84a209c5e0d4a24b00e52@6381723_oswg129508oswg1000oswg666_img_jpg?x-oss-process=image/quality,q_100/format,jpg/interlace,1\\\" /></p>\\n  <p>唐恺丨顺丰集团数智供应链解决方案事业群高级副总裁</p>\\n  <p>各位来宾下午好，很高兴来到亦庄这样的场合跟大家分享物流供应链AI的应用。</p>\\n  <p>开始之前跟大家讲一下供应链，从智能化视角或者数字化视角来看供应链，需要把供应链做一个抽象或者分层，统一来讲供应链是无从下手的，会用要素、链路、网络这三个层级去看整个供应链的协同以及看供应链的数字化进展和智能化进展，供应链基础要素我们叫作人车货场，所有供应链的动作和执行都是跟要素串联相关的，要素的调动形成链路，链路交织形成网络，单纯从顺丰来看，我们讲其中一个点顺丰自身在供应链领域的超大规模性，人车货场，人，在顺丰体系协同的员工超过一百万人的协同规模，整个车辆自有车辆超过20万辆，更大是中国的航空空运网络，中国有240架全货机，110架是在顺丰手上，更密集的航空网络是整个辅仓运力网络，客机辅仓也是运货的，辅仓运力三分之一是在顺丰的手上，也就是说今天中国头上飞过三架飞机，就有一架飞机运的是顺丰的货。</p>\\n  <p>在要素密集程度下，我们还要叠加链路复杂性，链路对于快递来说是收转运派，对于供应链叫作采购供应链、生产供应链、渠道供应链、消费供应链、售后供应链。收转运派四个环节听起来简单，整个运作过程中有120个环节串联起来，形成整个收转运派的链路，整个链路执行复杂度是非常高的，所有的链路交织形成大的网络，在大的网络中顺丰要做的一个事情，所有在上面的资源和链路需要做整个基于数字网络的智能调度和智能协同。今天顺丰为什么能够给客户做24小时达或者48小时达的承诺，因为所有链路调动过程中都是基于自主能力，我们叫作智能化、自主化做动态调度。</p>\\n  <p>动态调度，今天一个票件从北京发到深圳，该上什么飞机，用哪个小哥取件、哪个小哥派件，经过哪个中转场，静态路由是定好的，但是飞机会晚点，小哥会生病，汽车开在路上可能会抛锚，所有的节点都可能出现问题，顺丰一天处理五千万的票件，有50%的票件是要启动动态路由的，比如一个车在路径上不该停止的地方停止过长时间，系统会自动识别是否属于不正常状态，经过确认，比如他在高速上抛锚，整个系统会自动调度附近的空时车辆去做时效挽救，整个链路在24小时范围内要保证链路不出问题，基于大网络的资源协同和资源调度，必须由智能和数字化的事情来完成，不可能由人工完成。大模型是在2022年年底ChatGPT出来以后才火的，2016年我们就开始大规模地部署我们基于运筹算法、传统机器学习和强化学习智能化能力，是2025年唯一进入弗兰兹·厄德曼决赛的亚洲公司，这个奖项是运筹学界里最高奖项，代表了我们在整个运筹里的能力，传统机器学习能力，在整个大模型的时代开始大面积转向大模型的能力。</p>\\n  <p>在这样的复杂网络里，顺丰做的事情基于所有全链路端到端全量数字化全栈自研，从底层的能力，我们甚至有自己的地图部门，虽然可以使用高德导航、百度导航，但顺丰需要工业级导航，因此我们有自己的地图部门。我们导航的细度（远高于普通导航），你用百度只能导到小区，用丰图进到小区里可以知道怎么走，每个楼层都有哪些公司、住户，所有信息我们通过小哥每天的派送自动更新和采集，我们叫作全栈自研的能力。</p>\\n  <p>从2023年开始大面积构建大模型的网络和体系，现在我们大概有两个大的垂域模型，一个是丰遇大模型，这个是多模态大模型，主要是为内部相关业务使用的，包括网络调度、各种各样的细节应用。另外一个丰知大模型，面向行业推出的物流垂域大模型。今天整个模型应用，大家比较有感知的话题，比如Agent，我们从底层模型开放，再到Agent平台，再到市场，再到自构建的能力，在内部做了所有的转化，今天顺丰内部大概会有五千多个Agent是实时跑的，这里面有两百多个是官方Agent，比如智能网络调度Agent，运筹优化Agent，所有的Agent是200个是官方的，剩下4800个都是各个业务部门非技术人员，基于Agent平台在建的小Agent，大概每天消耗八百亿个token数量。</p>\\n  <p>基于我们对整个行业，对自身的数字化和智能化能力，我们把相应的能力，在要素复杂度、链路复杂度、网络复杂度上顺丰都有现成可考的模板。对于大多数公司，在要素、链路、网络复杂度是不如顺丰的，我们把能力进行抽象，形成几个大方面的能力，第一个垂域大模型，我们叫作物流决策大模型，基于丰知的产品体系来做。另外一个物流端到端的操作系统，我们叫作丰智云，还有面向合作伙伴LAAS物流开放平台，我们希望提供基于咨询、AI、数字化多链路服务，赋能整个行业，让每一家企业、行业、产业供应链都能变得更加聪明。</p>\\n  <p>丰知，我们通过丰知把我们所有传统的物流软件叠加Agent能力，稍微理解供应链就知道，供应链有一个仓储管理软件，我们希望提供给客户是直接带Agent能力的软件功能。这其中是差异可以这么理解，如果大家买一辆传统的汽车，你需要再买一个工具来使用它。如果大家买的是自动驾驶汽车，你是直接买服务的，工具需要人的使用变成服务，而自动驾驶汽车直接提供的是运人或者运货的服务，不需要有能力转化的，垂域应用领域我们直接提供Agent能力，我们通过丰知的AgentOS帮助企业快速建立我刚才讲的顺丰内部能力。还有一个Agent Studio，业务语义中心帮助大家在所有的数字化基础上去建构知识图谱模型，以前你的企业数据是给系统用的，但是我们通过语义中心，大模型自动建模，使得所有数据能够被Agent直接调用，通过Agent Studio在你已有的数字化平台上直接建构Agent应用，支持大面积使用。我们有两个底层应用做支撑，第一个丰知Code，用来做整个软件大规模定制的，把定制成本的边际成本降得非常低。还有一个丰知Evolver，大模型生成小模型，今天基于供应链的诊断和咨询，不是方法论先导，模型先导，我们希望通过数据，POC快速做咨询验证、供应链诊断，这部分会涉及到大量的模型生成，如何打开产能瓶颈，通过丰知Evolver、大模型自动生成小模型，大量生成定制化小模型，同时能够使模型调优时间大幅下降。</p>\\n  <p>这部分是大模型——物流决策大模型，做三个事，第一个供应链预测、供应链优化、供应链分析。</p>\\n  <p>供应链预测，我们做的是通过大模型的模态泛化，解决预测里很难做的几个特殊场景。比如新品预测和芯片预测，缺乏历史数据，以前的模型很难算得准，通过大模型做自动化咨询建模，以前是单SQ建模，现在是QA通道类的集群建模，使得整个数据关联性和数据补充性能够做得更好，在全球最大的咖啡连锁企业做的数据验证，大概能够提升5个点的准确率，是之前的模型完全没有办法做到的。</p>\\n  <p>另外一个供应链优化，我们通过大模型重写了以前运筹的经典模型，比如路径优化和专项优化场景，你用transformer架构重写这部分模型以后，运算时间提升一万倍左右，原来你做一个串点路径优化需要分钟级运算时间，现在可以下降到毫秒级，0.05秒就可以计算完成，资源消耗是之前的50分之一，以前要50个CPU来算，今天1个GPU就可以算完。</p>\\n  <p>另外一个分析的能力，这一部分分析的能力，大模型结合小模型，通过供应链智能体的方式来做这个事情，智能体在整个行业特别火的时候，是2025年3月份，2B应用我们很早就意识到，整个2B要解决模型黑盒的问题，解决模型高效和准确的问题，必须通过智能体的方式来做，2024年8月份在行业里推出供应链智能体综合应用的能力。</p>\\n  <p>在智能化之前，所有企业都逃不开的数字化第一步，模型再强，数据准确性、实时性、可靠性不够，肯定是得不到好的结果，在智能化之前，端到端数字化，我们通过丰智云链模型体系来做整个客户基于要素、链路的全链路数字化。</p>\\n  <p>最后讲一个案例，全球最大的咖啡连锁企业在中国有七千多家门店，2019年就开始帮他做智慧门店的系统，我们帮他做的是基于门店系统做门店级别的销售预测和补货预测，我们已经做了六年，我们用大模型帮他做传统模型的迭代。</p>\\n  <p>国际知名美妆巨头，在中国全渠道销售预测是我们帮他做的，为什么在中国的全渠道销售预测要我们做？因为中国渠道复杂度远超于任何一个单体国家，他的连锁企业在中国落地的实践经验比美国更加先进，之前跟美国的CIO聊，中国业务资本结构发生变化，中国主体收购了他在中国的业务，这一块暂时没有往前走。</p>\\n  <p>中国供应链深度、广度、复杂度是全球无二的，我们服务MNC企业的时候，我们在中国落地的供应链实践，就是全球最佳的供应链实践，在很多跨国企业客户上得到了验证，以前供应链数字化最佳实践叫作copy to china，今天做的事情是copy from china，在奢侈品行业，全球第一个智慧门店是长沙LV，我们帮他做的。工业制造领域伊顿供应链中台是在中国生产完成以后，再向亚太地区推的，我们给雀巢做高阶生产排程的POC，在中国不好用，需要中国的本土能力来做本土化实验，在数字化供应链叠加整个技术变革，叠加到AI能力越境的时候，我们看到更多的是中国有很大的机会窗口来做数字供应链全球最佳实践。</p>\\n  <p>我们也提出了从底层到上层所有能力，包括咨询诊断和顶规开始，再到大模型AI应用能力，以及到端到端的数字化能力，再结合到每个行业不同解决方案细化的能力，配合到供应链从采购供应链、渠道供应链、销售供应链、售后供应链全链路服务，今天我们希望跟更多的中国企业一起创造更多全球最佳供应链实践。</p>\\n  <p>谢谢大家。</p>\", \"language\": null}, \"published_parsed\": [2026, 5, 22, 6, 54, 18, 4, 142, 0]}, \"published_at\": \"2026-05-22 14:54:18\", \"ai_json_output\": \"\"}', 'AI究竟如何为产业创造价值？见证AI从“热点”转化为“生产力”的关键一跃。\n今天的顺丰已经用AI调度着中国三分之一的航空货运。从百万人的协同、二十万辆车的调度，到每天五千万票件的动态路由——物流供应链的复杂度，正是AI落地的最佳试验田。一个超大规模网络如何用大模型、Agent和运筹算法，将“24小时达”从承诺变成日常，并将这份能力输送给更多中国企业。\n以下为顺丰集团数智供应链解决方案事业群高级副总裁 唐恺 演讲内容，经36氪整理编辑：\n唐恺丨顺丰集团数智供应链解决方案事业群高级副总裁\n各位来宾下午好，很高兴来到亦庄这样的场合跟大家分享物流供应链AI的应用。\n开始之前跟大家讲一下供应链，从智能化视角或者数字化视角来看供应链，需要把供应链做一个抽象或者分层，统一来讲供应链是无从下手的，会用要素、链路、网络这三个层级去看整个供应链的协同以及看供应链的数字化进展和智能化进展，供应链基础要素我们叫作人车货场，所有供应链的动作和执行都是跟要素串联相关的，要素的调动形成链路，链路交织形成网络，单纯从顺丰来看，我们讲其中一个点顺丰自身在供应链领域的超大规模性，人车货场，人，在顺丰体系协同的员工超过一百万人的协同规模，整个车辆自有车辆超过20万辆，更大是中国的航空空运网络，中国有240架全货机，110架是在顺丰手上，更密集的航空网络是整个辅仓运力网络，客机辅仓也是运货的，辅仓运力三分之一是在顺丰的手上，也就是说今天中国头上飞过三架飞机，就有一架飞机运的是顺丰的货。\n在要素密集程度下，我们还要叠加链路复杂性，链路对于快递来说是收转运派，对于供应链叫作采购供应链、生产供应链、渠道供应链、消费供应链、售后供应链。收转运派四个环节听起来简单，整个运作过程中有120个环节串联起来，形成整个收转运派的链路，整个链路执行复杂度是非常高的，所有的链路交织形成大的网络，在大的网络中顺丰要做的一个事情，所有在上面的资源和链路需要做整个基于数字网络的智能调度和智能协同。今天顺丰为什么能够给客户做24小时达或者48小时达的承诺，因为所有链路调动过程中都是基于自主能力，我们叫作智能化、自主化做动态调度。\n动态调度，今天一个票件从北京发到深圳，该上什么飞机，用哪个小哥取件、哪个小哥派件，经过哪个中转场，静态路由是定好的，但是飞机会晚点，小哥会生病，汽车开在路上可能会抛锚，所有的节点都可能出现问题，顺丰一天处理五千万的票件，有50%的票件是要启动动态路由的，比如一个车在路径上不该停止的地方停止过长时间，系统会自动识别是否属于不正常状态，经过确认，比如他在高速上抛锚，整个系统会自动调度附近的空时车辆去做时效挽救，整个链路在24小时范围内要保证链路不出问题，基于大网络的资源协同和资源调度，必须由智能和数字化的事情来完成，不可能由人工完成。大模型是在2022年年底ChatGPT出来以后才火的，2016年我们就开始大规模地部署我们基于运筹算法、传统机器学习和强化学习智能化能力，是2025年唯一进入弗兰兹·厄德曼决赛的亚洲公司，这个奖项是运筹学界里最高奖项，代表了我们在整个运筹里的能力，传统机器学习能力，在整个大模型的时代开始大面积转向大模型的能力。\n在这样的复杂网络里，顺丰做的事情基于所有全链路端到端全量数字化全栈自研，从底层的能力，我们甚至有自己的地图部门，虽然可以使用高德导航、百度导航，但顺丰需要工业级导航，因此我们有自己的地图部门。我们导航的细度（远高于普通导航），你用百度只能导到小区，用丰图进到小区里可以知道怎么走，每个楼层都有哪些公司、住户，所有信息我们通过小哥每天的派送自动更新和采集，我们叫作全栈自研的能力。\n从2023年开始大面积构建大模型的网络和体系，现在我们大概有两个大的垂域模型，一个是丰遇大模型，这个是多模态大模型，主要是为内部相关业务使用的，包括网络调度、各种各样的细节应用。另外一个丰知大模型，面向行业推出的物流垂域大模型。今天整个模型应用，大家比较有感知的话题，比如Agent，我们从底层模型开放，再到Agent平台，再到市场，再到自构建的能力，在内部做了所有的转化，今天顺丰内部大概会有五千多个Agent是实时跑的，这里面有两百多个是官方Agent，比如智能网络调度Agent，运筹优化Agent，所有的Agent是200个是官方的，剩下4800个都是各个业务部门非技术人员，基于Agent平台在建的小Agent，大概每天消耗八百亿个token数量。\n基于我们对整个行业，对自身的数字化和智能化能力，我们把相应的能力，在要素复杂度、链路复杂度、网络复杂度上顺丰都有现成可考的模板。对于大多数公司，在要素、链路、网络复杂度是不如顺丰的，我们把能力进行抽象，形成几个大方面的能力，第一个垂域大模型，我们叫作物流决策大模型，基于丰知的产品体系来做。另外一个物流端到端的操作系统，我们叫作丰智云，还有面向合作伙伴LAAS物流开放平台，我们希望提供基于咨询、AI、数字化多链路服务，赋能整个行业，让每一家企业、行业、产业供应链都能变得更加聪明。\n丰知，我们通过丰知把我们所有传统的物流软件叠加Agent能力，稍微理解供应链就知道，供应链有一个仓储管理软件，我们希望提供给客户是直接带Agent能力的软件功能。这其中是差异可以这么理解，如果大家买一辆传统的汽车，你需要再买一个工具来使用它。如果大家买的是自动驾驶汽车，你是直接买服务的，工具需要人的使用变成服务，而自动驾驶汽车直接提供的是运人或者运货的服务，不需要有能力转化的，垂域应用领域我们直接提供Agent能力，我们通过丰知的AgentOS帮助企业快速建立我刚才讲的顺丰内部能力。还有一个Agent Studio，业务语义中心帮助大家在所有的数字化基础上去建构知识图谱模型，以前你的企业数据是给系统用的，但是我们通过语义中心，大模型自动建模，使得所有数据能够被Agent直接调用，通过Agent Studio在你已有的数字化平台上直接建构Agent应用，支持大面积使用。我们有两个底层应用做支撑，第一个丰知Code，用来做整个软件大规模定制的，把定制成本的边际成本降得非常低。还有一个丰知Evolver，大模型生成小模型，今天基于供应链的诊断和咨询，不是方法论先导，模型先导，我们希望通过数据，POC快速做咨询验证、供应链诊断，这部分会涉及到大量的模型生成，如何打开产能瓶颈，通过丰知Evolver、大模型自动生成小模型，大量生成定制化小模型，同时能够使模型调优时间大幅下降。\n这部分是大模型——物流决策大模型，做三个事，第一个供应链预测、供应链优化、供应链分析。\n供应链预测，我们做的是通过大模型的模态泛化，解决预测里很难做的几个特殊场景。比如新品预测和芯片预测，缺乏历史数据，以前的模型很难算得准，通过大模型做自动化咨询建模，以前是单SQ建模，现在是QA通道类的集群建模，使得整个数据关联性和数据补充性能够做得更好，在全球最大的咖啡连锁企业做的数据验证，大概能够提升5个点的准确率，是之前的模型完全没有办法做到的。\n另外一个供应链优化，我们通过大模型重写了以前运筹的经典模型，比如路径优化和专项优化场景，你用transformer架构重写这部分模型以后，运算时间提升一万倍左右，原来你做一个串点路径优化需要分钟级运算时间，现在可以下降到毫秒级，0.05秒就可以计算完成，资源消耗是之前的50分之一，以前要50个CPU来算，今天1个GPU就可以算完。\n另外一个分析的能力，这一部分分析的能力，大模型结合小模型，通过供应链智能体的方式来做这个事情，智能体在整个行业特别火的时候，是2025年3月份，2B应用我们很早就意识到，整个2B要解决模型黑盒的问题，解决模型高效和准确的问题，必须通过智能体的方式来做，2024年8月份在行业里推出供应链智能体综合应用的能力。\n在智能化之前，所有企业都逃不开的数字化第一步，模型再强，数据准确性、实时性、可靠性不够，肯定是得不到好的结果，在智能化之前，端到端数字化，我们通过丰智云链模型体系来做整个客户基于要素、链路的全链路数字化。\n最后讲一个案例，全球最大的咖啡连锁企业在中国有七千多家门店，2019年就开始帮他做智慧门店的系统，我们帮他做的是基于门店系统做门店级别的销售预测和补货预测，我们已经做了六年，我们用大模型帮他做传统模型的迭代。\n国际知名美妆巨头，在中国全渠道销售预测是我们帮他做的，为什么在中国的全渠道销售预测要我们做？因为中国渠道复杂度远超于任何一个单体国家，他的连锁企业在中国落地的实践经验比美国更加先进，之前跟美国的CIO聊，中国业务资本结构发生变化，中国主体收购了他在中国的业务，这一块暂时没有往前走。\n中国供应链深度、广度、复杂度是全球无二的，我们服务MNC企业的时候，我们在中国落地的供应链实践，就是全球最佳的供应链实践，在很多跨国企业客户上得到了验证，以前供应链数字化最佳实践叫作copy to china，今天做的事情是copy from china，在奢侈品行业，全球第一个智慧门店是长沙LV，我们帮他做的。工业制造领域伊顿供应链中台是在中国生产完成以后，再向亚太地区推的，我们给雀巢做高阶生产排程的POC，在中国不好用，需要中国的本土能力来做本土化实验，在数字化供应链叠加整个技术变革，叠加到AI能力越境的时候，我们看到更多的是中国有很大的机会窗口来做数字供应链全球最佳实践。\n我们也提出了从底层到上层所有能力，包括咨询诊断和顶规开始，再到大模型AI应用能力，以及到端到端的数字化能力，再结合到每个行业不同解决方案细化的能力，配合到供应链从采购供应链、渠道供应链、销售供应链、售后供应链全链路服务，今天我们希望跟更多的中国企业一起创造更多全球最佳供应链实践。\n谢谢大家。', NULL, '2026-05-22 15:55:58');
INSERT INTO `news_detail` VALUES (150, 4321, 8, '新能源与汽车', '36氪首发 | 军工背景团队切入船舶电动化，已拿下海南华铁500艘订单', '', '作者丨欧雪\n\n编辑丨袁斯来\n\n硬氪获悉，新能源船舶三电系统全栈供应商比电科技近日完成数千万元A轮融资，本轮投资方由金桥基金及其他产业化资本构成，投中资本担任长期战略财务顾问。资金将主要用于模组和集装箱式电池的开发及取证、研发团队扩充、自动化产线建设及市场拓展。\n\n比电科技成立于2023年，总部位于连云港，聚焦新能源船舶电动化与智能化升级，构建覆盖电池系统、电控系统、电驱系统及船舶能源管理系统的全栈产品体系，形成“三电+AI”核心技术底座。\n\n比电科技创始人袁伟毕业于华北电力大学，曾就职于国家保密技术研究所，后长期从事军工行业。2023年，团队判断军工业务面临调整，同时看好船舶电动化方向，遂转型切入该赛道。\n\n在“双碳”目标与航运业绿色转型加速的背景下，船舶电动化正进入快速成长期。据交通运输部统计，截至2023年底，我国内河运输船舶保有量超10万艘。有行业研究认为，若仅考虑纯电动货船等严格意义上的新能源船舶，其渗透率尚不足2%。另据EVTank等机构预测，2026年我国电动船舶对动力电池的需求量将达到11.2GWh。\n\n2024年8月，国家交通部出台老旧船舶改造及新建补贴政策，多地同步推出过闸优先、通行费减免等配套措施。袁伟判断：“当前阶段相当于新能源车2012年前后的水平，行业正从政策驱动转向市场驱动，未来几年将进入快速爆发期。”\n\n船舶电动化的核心难点在于复杂系统的长期稳定运行与多方协同交付。比电科技通过“小船规模化验证+中大型船舶系统突破”的路径，已完成从0到1的商业化闭环。\n\n成立一年时间内，公司已取得中国船级社（CCS）型式认可、欧盟CE及UN38.3等国内外权威认证，已具备从小型船舶到2000吨级中大型电动运输船的系统级交付能力。\n\n截至目前，公司累计交付各类船舶超百艘，覆盖无人船、清洁船、保障船及客渡船等细分场景。团队作为船东代表，全程参与国内收批次纯电动货运船，此船载重2000吨，配备300KW的电推，以700余伏的电压平台，搭在3500KWH电量。截止到现在，此船已经运营超过2万公里，整套系统运行正常，验证了公司在中大型电动船的系统集成及交付能力。\n\n2026年一季度，公司营收同比超200%，集中交付在3-4季度，公司有望在年中实现盈亏平衡。\n\n在客户拓展方面，比电科技今年年初与上市公司海南华铁联航科技有限公司签署未来3年交付500艘新能源游艇合同，四月份完成与航犀物流签署未来2年交付30艘纯电工程船设计及三电合同。\n\n同时，公司重点面向占国内货运船总量70%的私人船东，通过提供前期船舶设计及船级社审图等增值服务，绑定三电系统供应，已锁定数百艘潜在改造订单。\n\n海外市场方面，公司自2024年下半年起布局东南亚及中亚地区，主要面向大宗货物运输场景，通过与国内头部物流公司合作供应船舶。袁伟透露：“海外价格比国内好很多，未来会是重要增长极。”\n\n此外，公司正切入海洋牧场等近海新兴场景，探索以“无人船+无人机+海上风电/光伏”构建的微电网模式，为沿海养殖提供一体化能源解决方案。\n\n以下是对袁伟的访谈节选：\n\n硬氪：船舶电动化与汽车电动化最大的不同是什么？比电的核心壁垒在哪里？\n\n袁伟：船和车最大的区别在于体量。一辆车电池约100度电，而一艘船动辄三五千度。这种量级跃迁，使得电控系统、BMS、DC/DC都与车完全不同。经过这一两年的积累，三级架构（主控-从控-电芯级）已相对成熟，真正的壁垒在于系统集成能力和对船舶工况的深度理解。\n\n此外，船舶行业“重认证、重工程、重交付”。我们花了近两年时间打磨产品，完成CCS认证，跑通从设计、审图到交付的全流程。这不是单纯买电芯组装就能做到的。\n\n硬氪：成立时间不长，如何拿到过亿订单并绑定私人船东？\n\n袁伟：国内70%的货运船掌握在私人手里，他们讲究性价比。我们和其他竞争对手的一个差异化优势是：可以帮船东做前期的船舶设计和船级社审图。过去找设计院可能要花几十万，我们前期帮他解决这个问题，条件是用我们的三电系统。\n\n另外，货运船东很多来自安徽、河南等省，以家族形式运营。我们通过资源积累，绑定了三四个家族，未来可预期的改造订单就有几百艘。\n\n硬氪：接下来两到三年的战略重点是什么？\n\n袁伟：一是完成现有订单的批量交付，在客渡船和货运船形成规模化效应。二是重点开发具身智能箱式电源和智能船舶数据决策系统，实现从被动防护到主动智能管理和从单点功能到全船智能协同的跃迁。三是向近海拓展，包括游艇和海洋牧场。海洋牧场的能源中枢控制目前还是空白，比电科技通过“AI视觉预警+三电底层”的水上生命底盘，以及深远海“AI微电网大脑”，打造“零事故、零排放”的智慧系统。\n\n投资方观点：\n\n金桥基金表示：我们长期看好船舶与航运产业的绿色升级方向，比电科技在其所处的产业位置与能力结构具备明显稀缺性，公司具备真正的“全船能源系统”级别能力，而非简单设备集成；另一方面，比电已完成从小型船舶到2000吨级运输船的跨船型交付验证，证明其技术不仅成立，更具备规模化复制的工程基础；最后，公司已成功取得过亿订单，给后续发展打造了坚实基础，体现了比电科技在行业早期阶段具备难以复制的先发优势。随着船舶电动化与智能化持续发展，比电科技于2026年起，也将在海洋牧场、游艇智驾等多元场景持续拓展应用边界，并依托内河与沿海产业基础，加速向海外市场延伸，面向全球市场提前布局。在此，也祝贺比电科技顺利完成本轮融资，期待公司在新的发展阶段不断突破，共同推动中国船舶电动化迈向更高水平。', 'https://36kr.com/p/3820087713403270?f=rss', 0, '', '{\"summary\": \"本文介绍新能源船舶三电企业比电科技的发展及出海布局，可为计划布局海外船舶电动化赛道的企业提供参考\", \"abstract\": \"有军工背景的新能源船舶三电全栈供应商比电科技近日完成数千万元A轮融资，资金将用于产品研发、产线建设与市场拓展。当前国内船舶电动化渗透率不足2%，在国家老旧船舶改造补贴等政策推动下，行业正从政策驱动转向市场驱动，即将进入快速爆发期。比电科技已完成多船型交付验证，拿下数百艘国内订单，并已布局东南亚、中亚海外市场，将海外作为未来重要增长极。投资方长期看好船舶航运绿色升级赛道，认为比电科技具备难以复制的先发优势。\", \"keywords\": [\"船舶电动化\", \"新能源船舶\", \"三电系统\", \"海外布局\", \"绿色转型\", \"权威认证\", \"双碳目标\"], \"policy_risk\": {\"market_risk\": \"未提及\", \"policy_compliance\": \"2024年8月国家交通部出台老旧船舶改造及新建补贴政策，多地同步推出过闸优先、通行费减免等配套措施支持船舶电动化发展；船舶三电系统需取得中国船级社、欧盟CE、UN38.3等国内外权威认证方可进入市场\"}, \"topic_cluster\": \"海外市场洞察\", \"industry_category\": \"新能源与汽车\"}', '', '{\"url\": \"https://36kr.com/p/3820087713403270?f=rss\", \"title\": \"36氪首发 | 军工背景团队切入船舶电动化，已拿下海南华铁500艘订单\", \"source\": \"https://36kr.com/feed\", \"content\": \"作者丨欧雪\\n\\n编辑丨袁斯来\\n\\n硬氪获悉，新能源船舶三电系统全栈供应商比电科技近日完成数千万元A轮融资，本轮投资方由金桥基金及其他产业化资本构成，投中资本担任长期战略财务顾问。资金将主要用于模组和集装箱式电池的开发及取证、研发团队扩充、自动化产线建设及市场拓展。\\n\\n比电科技成立于2023年，总部位于连云港，聚焦新能源船舶电动化与智能化升级，构建覆盖电池系统、电控系统、电驱系统及船舶能源管理系统的全栈产品体系，形成“三电+AI”核心技术底座。\\n\\n比电科技创始人袁伟毕业于华北电力大学，曾就职于国家保密技术研究所，后长期从事军工行业。2023年，团队判断军工业务面临调整，同时看好船舶电动化方向，遂转型切入该赛道。\\n\\n在“双碳”目标与航运业绿色转型加速的背景下，船舶电动化正进入快速成长期。据交通运输部统计，截至2023年底，我国内河运输船舶保有量超10万艘。有行业研究认为，若仅考虑纯电动货船等严格意义上的新能源船舶，其渗透率尚不足2%。另据EVTank等机构预测，2026年我国电动船舶对动力电池的需求量将达到11.2GWh。\\n\\n2024年8月，国家交通部出台老旧船舶改造及新建补贴政策，多地同步推出过闸优先、通行费减免等配套措施。袁伟判断：“当前阶段相当于新能源车2012年前后的水平，行业正从政策驱动转向市场驱动，未来几年将进入快速爆发期。”\\n\\n船舶电动化的核心难点在于复杂系统的长期稳定运行与多方协同交付。比电科技通过“小船规模化验证+中大型船舶系统突破”的路径，已完成从0到1的商业化闭环。\\n\\n成立一年时间内，公司已取得中国船级社（CCS）型式认可、欧盟CE及UN38.3等国内外权威认证，已具备从小型船舶到2000吨级中大型电动运输船的系统级交付能力。\\n\\n截至目前，公司累计交付各类船舶超百艘，覆盖无人船、清洁船、保障船及客渡船等细分场景。团队作为船东代表，全程参与国内收批次纯电动货运船，此船载重2000吨，配备300KW的电推，以700余伏的电压平台，搭在3500KWH电量。截止到现在，此船已经运营超过2万公里，整套系统运行正常，验证了公司在中大型电动船的系统集成及交付能力。\\n\\n2026年一季度，公司营收同比超200%，集中交付在3-4季度，公司有望在年中实现盈亏平衡。\\n\\n在客户拓展方面，比电科技今年年初与上市公司海南华铁联航科技有限公司签署未来3年交付500艘新能源游艇合同，四月份完成与航犀物流签署未来2年交付30艘纯电工程船设计及三电合同。\\n\\n同时，公司重点面向占国内货运船总量70%的私人船东，通过提供前期船舶设计及船级社审图等增值服务，绑定三电系统供应，已锁定数百艘潜在改造订单。\\n\\n海外市场方面，公司自2024年下半年起布局东南亚及中亚地区，主要面向大宗货物运输场景，通过与国内头部物流公司合作供应船舶。袁伟透露：“海外价格比国内好很多，未来会是重要增长极。”\\n\\n此外，公司正切入海洋牧场等近海新兴场景，探索以“无人船+无人机+海上风电/光伏”构建的微电网模式，为沿海养殖提供一体化能源解决方案。\\n\\n以下是对袁伟的访谈节选：\\n\\n硬氪：船舶电动化与汽车电动化最大的不同是什么？比电的核心壁垒在哪里？\\n\\n袁伟：船和车最大的区别在于体量。一辆车电池约100度电，而一艘船动辄三五千度。这种量级跃迁，使得电控系统、BMS、DC/DC都与车完全不同。经过这一两年的积累，三级架构（主控-从控-电芯级）已相对成熟，真正的壁垒在于系统集成能力和对船舶工况的深度理解。\\n\\n此外，船舶行业“重认证、重工程、重交付”。我们花了近两年时间打磨产品，完成CCS认证，跑通从设计、审图到交付的全流程。这不是单纯买电芯组装就能做到的。\\n\\n硬氪：成立时间不长，如何拿到过亿订单并绑定私人船东？\\n\\n袁伟：国内70%的货运船掌握在私人手里，他们讲究性价比。我们和其他竞争对手的一个差异化优势是：可以帮船东做前期的船舶设计和船级社审图。过去找设计院可能要花几十万，我们前期帮他解决这个问题，条件是用我们的三电系统。\\n\\n另外，货运船东很多来自安徽、河南等省，以家族形式运营。我们通过资源积累，绑定了三四个家族，未来可预期的改造订单就有几百艘。\\n\\n硬氪：接下来两到三年的战略重点是什么？\\n\\n袁伟：一是完成现有订单的批量交付，在客渡船和货运船形成规模化效应。二是重点开发具身智能箱式电源和智能船舶数据决策系统，实现从被动防护到主动智能管理和从单点功能到全船智能协同的跃迁。三是向近海拓展，包括游艇和海洋牧场。海洋牧场的能源中枢控制目前还是空白，比电科技通过“AI视觉预警+三电底层”的水上生命底盘，以及深远海“AI微电网大脑”，打造“零事故、零排放”的智慧系统。\\n\\n投资方观点：\\n\\n金桥基金表示：我们长期看好船舶与航运产业的绿色升级方向，比电科技在其所处的产业位置与能力结构具备明显稀缺性，公司具备真正的“全船能源系统”级别能力，而非简单设备集成；另一方面，比电已完成从小型船舶到2000吨级运输船的跨船型交付验证，证明其技术不仅成立，更具备规模化复制的工程基础；最后，公司已成功取得过亿订单，给后续发展打造了坚实基础，体现了比电科技在行业早期阶段具备难以复制的先发优势。随着船舶电动化与智能化持续发展，比电科技于2026年起，也将在海洋牧场、游艇智驾等多元场景持续拓展应用边界，并依托内河与沿海产业基础，加速向海外市场延伸，面向全球市场提前布局。在此，也祝贺比电科技顺利完成本轮融资，期待公司在新的发展阶段不断突破，共同推动中国船舶电动化迈向更高水平。\", \"is_policy\": 0, \"origin_msg\": {\"link\": \"https://36kr.com/p/3820087713403270?f=rss\", \"links\": [{\"rel\": \"alternate\", \"href\": \"https://36kr.com/p/3820087713403270?f=rss\", \"type\": \"text/html\"}], \"title\": \"36氪首发 | 军工背景团队切入船舶电动化，已拿下海南华铁500艘订单\", \"source\": {\"title\": \"36氪\"}, \"summary\": \"<p>作者丨欧雪</p>\\n  <p>编辑丨袁斯来</p>\\n  <p>硬氪获悉，新能源船舶三电系统全栈供应商比电科技近日完成数千万元A轮融资，本轮投资方由金桥基金及其他产业化资本构成，投中资本担任长期战略财务顾问。资金将主要用于模组和集装箱式电池的开发及取证、研发团队扩充、自动化产线建设及市场拓展。</p>\\n  <p>比电科技成立于2023年，总部位于连云港，聚焦新能源船舶电动化与智能化升级，构建覆盖电池系统、电控系统、电驱系统及船舶能源管理系统的全栈产品体系，形成“三电+AI”核心技术底座。</p>\\n  <p>比电科技创始人袁伟毕业于华北电力大学，曾就职于国家保密技术研究所，后长期从事军工行业。2023年，团队判断军工业务面临调整，同时看好船舶电动化方向，遂转型切入该赛道。</p>\\n  <p>在“双碳”目标与航运业绿色转型加速的背景下，船舶电动化正进入快速成长期。据交通运输部统计，截至2023年底，我国内河运输船舶保有量超10万艘。有行业研究认为，若仅考虑纯电动货船等严格意义上的新能源船舶，其渗透率尚不足2%。另据EVTank等机构预测，2026年我国电动船舶对动力电池的需求量将达到11.2GWh。</p>\\n  <p>2024年8月，国家交通部出台老旧船舶改造及新建补贴政策，多地同步推出过闸优先、通行费减免等配套措施。袁伟判断：“当前阶段相当于新能源车2012年前后的水平，行业正从政策驱动转向市场驱动，未来几年将进入快速爆发期。”</p>\\n  <p>船舶电动化的核心难点在于复杂系统的长期稳定运行与多方协同交付。比电科技通过“小船规模化验证+中大型船舶系统突破”的路径，已完成从0到1的商业化闭环。</p>\\n  <p>成立一年时间内，公司已取得中国船级社（CCS）型式认可、欧盟CE及UN38.3等国内外权威认证，已具备从小型船舶到2000吨级中大型电动运输船的系统级交付能力。</p>\\n  <p>截至目前，公司累计交付各类船舶超百艘，覆盖无人船、清洁船、保障船及客渡船等细分场景。团队作为船东代表，全程参与国内收批次纯电动货运船，此船载重2000吨，配备300KW的电推，以700余伏的电压平台，搭在3500KWH电量。截止到现在，此船已经运营超过2万公里，整套系统运行正常，验证了公司在中大型电动船的系统集成及交付能力。</p>\\n  <p>2026年一季度，公司营收同比超200%，集中交付在3-4季度，公司有望在年中实现盈亏平衡。</p>\\n  <p>在客户拓展方面，比电科技今年年初与上市公司海南华铁联航科技有限公司签署未来3年交付500艘新能源游艇合同，四月份完成与航犀物流签署未来2年交付30艘纯电工程船设计及三电合同。</p>\\n  <p>同时，公司重点面向占国内货运船总量70%的私人船东，通过提供前期船舶设计及船级社审图等增值服务，绑定三电系统供应，已锁定数百艘潜在改造订单。</p>\\n  <p>海外市场方面，公司自2024年下半年起布局东南亚及中亚地区，主要面向大宗货物运输场景，通过与国内头部物流公司合作供应船舶。袁伟透露：“海外价格比国内好很多，未来会是重要增长极。”</p>\\n  <p>此外，公司正切入海洋牧场等近海新兴场景，探索以“无人船+无人机+海上风电/光伏”构建的微电网模式，为沿海养殖提供一体化能源解决方案。</p>\\n  <p><strong>以下是对袁伟的访谈节选：</strong></p>\\n  <p><strong>硬氪：船舶电动化与汽车电动化最大的不同是什么？比电的核心壁垒在哪里？</strong></p>\\n  <p><strong>袁伟：</strong>船和车最大的区别在于体量。一辆车电池约100度电，而一艘船动辄三五千度。这种量级跃迁，使得电控系统、BMS、DC/DC都与车完全不同。经过这一两年的积累，三级架构（主控-从控-电芯级）已相对成熟，真正的壁垒在于系统集成能力和对船舶工况的深度理解。</p>\\n  <p>此外，船舶行业“重认证、重工程、重交付”。我们花了近两年时间打磨产品，完成CCS认证，跑通从设计、审图到交付的全流程。这不是单纯买电芯组装就能做到的。</p>\\n  <p><strong>硬氪：成立时间不长，如何拿到过亿订单并绑定私人船东？</strong></p>\\n  <p><strong>袁伟：</strong>国内70%的货运船掌握在私人手里，他们讲究性价比。我们和其他竞争对手的一个差异化优势是：可以帮船东做前期的船舶设计和船级社审图。过去找设计院可能要花几十万，我们前期帮他解决这个问题，条件是用我们的三电系统。</p>\\n  <p>另外，货运船东很多来自安徽、河南等省，以家族形式运营。我们通过资源积累，绑定了三四个家族，未来可预期的改造订单就有几百艘。</p>\\n  <p><strong>硬氪：接下来两到三年的战略重点是什么？</strong></p>\\n  <p><strong>袁伟：</strong>一是完成现有订单的批量交付，在客渡船和货运船形成规模化效应。二是重点开发具身智能箱式电源和智能船舶数据决策系统，实现从被动防护到主动智能管理和从单点功能到全船智能协同的跃迁。三是向近海拓展，包括游艇和海洋牧场。海洋牧场的能源中枢控制目前还是空白，比电科技通过“AI视觉预警+三电底层”的水上生命底盘，以及深远海“AI微电网大脑”，打造“零事故、零排放”的智慧系统。</p>\\n  <p><strong>投资方观点：</strong></p>\\n  <p><strong>金桥基金表示：</strong>我们长期看好船舶与航运产业的绿色升级方向，比电科技在其所处的产业位置与能力结构具备明显稀缺性，公司具备真正的“全船能源系统”级别能力，而非简单设备集成；另一方面，比电已完成从小型船舶到2000吨级运输船的跨船型交付验证，证明其技术不仅成立，更具备规模化复制的工程基础；最后，公司已成功取得过亿订单，给后续发展打造了坚实基础，体现了比电科技在行业早期阶段具备难以复制的先发优势。随着船舶电动化与智能化持续发展，比电科技于2026年起，也将在海洋牧场、游艇智驾等多元场景持续拓展应用边界，并依托内河与沿海产业基础，加速向海外市场延伸，面向全球市场提前布局。在此，也祝贺比电科技顺利完成本轮融资，期待公司在新的发展阶段不断突破，共同推动中国船舶电动化迈向更高水平。</p>\", \"published\": \"2026-05-22 14:34:22  +0800\", \"title_detail\": {\"base\": \"https://36kr.com/feed\", \"type\": \"text/plain\", \"value\": \"36氪首发 | 军工背景团队切入船舶电动化，已拿下海南华铁500艘订单\", \"language\": null}, \"summary_detail\": {\"base\": \"https://36kr.com/feed\", \"type\": \"text/html\", \"value\": \"<p>作者丨欧雪</p>\\n  <p>编辑丨袁斯来</p>\\n  <p>硬氪获悉，新能源船舶三电系统全栈供应商比电科技近日完成数千万元A轮融资，本轮投资方由金桥基金及其他产业化资本构成，投中资本担任长期战略财务顾问。资金将主要用于模组和集装箱式电池的开发及取证、研发团队扩充、自动化产线建设及市场拓展。</p>\\n  <p>比电科技成立于2023年，总部位于连云港，聚焦新能源船舶电动化与智能化升级，构建覆盖电池系统、电控系统、电驱系统及船舶能源管理系统的全栈产品体系，形成“三电+AI”核心技术底座。</p>\\n  <p>比电科技创始人袁伟毕业于华北电力大学，曾就职于国家保密技术研究所，后长期从事军工行业。2023年，团队判断军工业务面临调整，同时看好船舶电动化方向，遂转型切入该赛道。</p>\\n  <p>在“双碳”目标与航运业绿色转型加速的背景下，船舶电动化正进入快速成长期。据交通运输部统计，截至2023年底，我国内河运输船舶保有量超10万艘。有行业研究认为，若仅考虑纯电动货船等严格意义上的新能源船舶，其渗透率尚不足2%。另据EVTank等机构预测，2026年我国电动船舶对动力电池的需求量将达到11.2GWh。</p>\\n  <p>2024年8月，国家交通部出台老旧船舶改造及新建补贴政策，多地同步推出过闸优先、通行费减免等配套措施。袁伟判断：“当前阶段相当于新能源车2012年前后的水平，行业正从政策驱动转向市场驱动，未来几年将进入快速爆发期。”</p>\\n  <p>船舶电动化的核心难点在于复杂系统的长期稳定运行与多方协同交付。比电科技通过“小船规模化验证+中大型船舶系统突破”的路径，已完成从0到1的商业化闭环。</p>\\n  <p>成立一年时间内，公司已取得中国船级社（CCS）型式认可、欧盟CE及UN38.3等国内外权威认证，已具备从小型船舶到2000吨级中大型电动运输船的系统级交付能力。</p>\\n  <p>截至目前，公司累计交付各类船舶超百艘，覆盖无人船、清洁船、保障船及客渡船等细分场景。团队作为船东代表，全程参与国内收批次纯电动货运船，此船载重2000吨，配备300KW的电推，以700余伏的电压平台，搭在3500KWH电量。截止到现在，此船已经运营超过2万公里，整套系统运行正常，验证了公司在中大型电动船的系统集成及交付能力。</p>\\n  <p>2026年一季度，公司营收同比超200%，集中交付在3-4季度，公司有望在年中实现盈亏平衡。</p>\\n  <p>在客户拓展方面，比电科技今年年初与上市公司海南华铁联航科技有限公司签署未来3年交付500艘新能源游艇合同，四月份完成与航犀物流签署未来2年交付30艘纯电工程船设计及三电合同。</p>\\n  <p>同时，公司重点面向占国内货运船总量70%的私人船东，通过提供前期船舶设计及船级社审图等增值服务，绑定三电系统供应，已锁定数百艘潜在改造订单。</p>\\n  <p>海外市场方面，公司自2024年下半年起布局东南亚及中亚地区，主要面向大宗货物运输场景，通过与国内头部物流公司合作供应船舶。袁伟透露：“海外价格比国内好很多，未来会是重要增长极。”</p>\\n  <p>此外，公司正切入海洋牧场等近海新兴场景，探索以“无人船+无人机+海上风电/光伏”构建的微电网模式，为沿海养殖提供一体化能源解决方案。</p>\\n  <p><strong>以下是对袁伟的访谈节选：</strong></p>\\n  <p><strong>硬氪：船舶电动化与汽车电动化最大的不同是什么？比电的核心壁垒在哪里？</strong></p>\\n  <p><strong>袁伟：</strong>船和车最大的区别在于体量。一辆车电池约100度电，而一艘船动辄三五千度。这种量级跃迁，使得电控系统、BMS、DC/DC都与车完全不同。经过这一两年的积累，三级架构（主控-从控-电芯级）已相对成熟，真正的壁垒在于系统集成能力和对船舶工况的深度理解。</p>\\n  <p>此外，船舶行业“重认证、重工程、重交付”。我们花了近两年时间打磨产品，完成CCS认证，跑通从设计、审图到交付的全流程。这不是单纯买电芯组装就能做到的。</p>\\n  <p><strong>硬氪：成立时间不长，如何拿到过亿订单并绑定私人船东？</strong></p>\\n  <p><strong>袁伟：</strong>国内70%的货运船掌握在私人手里，他们讲究性价比。我们和其他竞争对手的一个差异化优势是：可以帮船东做前期的船舶设计和船级社审图。过去找设计院可能要花几十万，我们前期帮他解决这个问题，条件是用我们的三电系统。</p>\\n  <p>另外，货运船东很多来自安徽、河南等省，以家族形式运营。我们通过资源积累，绑定了三四个家族，未来可预期的改造订单就有几百艘。</p>\\n  <p><strong>硬氪：接下来两到三年的战略重点是什么？</strong></p>\\n  <p><strong>袁伟：</strong>一是完成现有订单的批量交付，在客渡船和货运船形成规模化效应。二是重点开发具身智能箱式电源和智能船舶数据决策系统，实现从被动防护到主动智能管理和从单点功能到全船智能协同的跃迁。三是向近海拓展，包括游艇和海洋牧场。海洋牧场的能源中枢控制目前还是空白，比电科技通过“AI视觉预警+三电底层”的水上生命底盘，以及深远海“AI微电网大脑”，打造“零事故、零排放”的智慧系统。</p>\\n  <p><strong>投资方观点：</strong></p>\\n  <p><strong>金桥基金表示：</strong>我们长期看好船舶与航运产业的绿色升级方向，比电科技在其所处的产业位置与能力结构具备明显稀缺性，公司具备真正的“全船能源系统”级别能力，而非简单设备集成；另一方面，比电已完成从小型船舶到2000吨级运输船的跨船型交付验证，证明其技术不仅成立，更具备规模化复制的工程基础；最后，公司已成功取得过亿订单，给后续发展打造了坚实基础，体现了比电科技在行业早期阶段具备难以复制的先发优势。随着船舶电动化与智能化持续发展，比电科技于2026年起，也将在海洋牧场、游艇智驾等多元场景持续拓展应用边界，并依托内河与沿海产业基础，加速向海外市场延伸，面向全球市场提前布局。在此，也祝贺比电科技顺利完成本轮融资，期待公司在新的发展阶段不断突破，共同推动中国船舶电动化迈向更高水平。</p>\", \"language\": null}, \"published_parsed\": [2026, 5, 22, 6, 34, 22, 4, 142, 0]}, \"published_at\": \"2026-05-22 14:34:22\", \"ai_json_output\": \"\"}', '作者丨欧雪\n编辑丨袁斯来\n硬氪获悉，新能源船舶三电系统全栈供应商比电科技近日完成数千万元A轮融资，本轮投资方由金桥基金及其他产业化资本构成，投中资本担任长期战略财务顾问。资金将主要用于模组和集装箱式电池的开发及取证、研发团队扩充、自动化产线建设及市场拓展。\n比电科技成立于2023年，总部位于连云港，聚焦新能源船舶电动化与智能化升级，构建覆盖电池系统、电控系统、电驱系统及船舶能源管理系统的全栈产品体系，形成“三电+AI”核心技术底座。\n比电科技创始人袁伟毕业于华北电力大学，曾就职于国家保密技术研究所，后长期从事军工行业。2023年，团队判断军工业务面临调整，同时看好船舶电动化方向，遂转型切入该赛道。\n在“双碳”目标与航运业绿色转型加速的背景下，船舶电动化正进入快速成长期。据交通运输部统计，截至2023年底，我国内河运输船舶保有量超10万艘。有行业研究认为，若仅考虑纯电动货船等严格意义上的新能源船舶，其渗透率尚不足2%。另据EVTank等机构预测，2026年我国电动船舶对动力电池的需求量将达到11.2GWh。\n2024年8月，国家交通部出台老旧船舶改造及新建补贴政策，多地同步推出过闸优先、通行费减免等配套措施。袁伟判断：“当前阶段相当于新能源车2012年前后的水平，行业正从政策驱动转向市场驱动，未来几年将进入快速爆发期。”\n船舶电动化的核心难点在于复杂系统的长期稳定运行与多方协同交付。比电科技通过“小船规模化验证+中大型船舶系统突破”的路径，已完成从0到1的商业化闭环。\n成立一年时间内，公司已取得中国船级社（CCS）型式认可、欧盟CE及UN38.3等国内外权威认证，已具备从小型船舶到2000吨级中大型电动运输船的系统级交付能力。\n截至目前，公司累计交付各类船舶超百艘，覆盖无人船、清洁船、保障船及客渡船等细分场景。团队作为船东代表，全程参与国内收批次纯电动货运船，此船载重2000吨，配备300KW的电推，以700余伏的电压平台，搭在3500KWH电量。截止到现在，此船已经运营超过2万公里，整套系统运行正常，验证了公司在中大型电动船的系统集成及交付能力。\n2026年一季度，公司营收同比超200%，集中交付在3-4季度，公司有望在年中实现盈亏平衡。\n在客户拓展方面，比电科技今年年初与上市公司海南华铁联航科技有限公司签署未来3年交付500艘新能源游艇合同，四月份完成与航犀物流签署未来2年交付30艘纯电工程船设计及三电合同。\n同时，公司重点面向占国内货运船总量70%的私人船东，通过提供前期船舶设计及船级社审图等增值服务，绑定三电系统供应，已锁定数百艘潜在改造订单。\n海外市场方面，公司自2024年下半年起布局东南亚及中亚地区，主要面向大宗货物运输场景，通过与国内头部物流公司合作供应船舶。袁伟透露：“海外价格比国内好很多，未来会是重要增长极。”\n此外，公司正切入海洋牧场等近海新兴场景，探索以“无人船+无人机+海上风电/光伏”构建的微电网模式，为沿海养殖提供一体化能源解决方案。\n以下是对袁伟的访谈节选：\n硬氪：船舶电动化与汽车电动化最大的不同是什么？比电的核心壁垒在哪里？\n袁伟：\n船和车最大的区别在于体量。一辆车电池约100度电，而一艘船动辄三五千度。这种量级跃迁，使得电控系统、BMS、DC/DC都与车完全不同。经过这一两年的积累，三级架构（主控-从控-电芯级）已相对成熟，真正的壁垒在于系统集成能力和对船舶工况的深度理解。\n此外，船舶行业“重认证、重工程、重交付”。我们花了近两年时间打磨产品，完成CCS认证，跑通从设计、审图到交付的全流程。这不是单纯买电芯组装就能做到的。\n硬氪：成立时间不长，如何拿到过亿订单并绑定私人船东？\n袁伟：\n国内70%的货运船掌握在私人手里，他们讲究性价比。我们和其他竞争对手的一个差异化优势是：可以帮船东做前期的船舶设计和船级社审图。过去找设计院可能要花几十万，我们前期帮他解决这个问题，条件是用我们的三电系统。\n另外，货运船东很多来自安徽、河南等省，以家族形式运营。我们通过资源积累，绑定了三四个家族，未来可预期的改造订单就有几百艘。\n硬氪：接下来两到三年的战略重点是什么？\n袁伟：\n一是完成现有订单的批量交付，在客渡船和货运船形成规模化效应。二是重点开发具身智能箱式电源和智能船舶数据决策系统，实现从被动防护到主动智能管理和从单点功能到全船智能协同的跃迁。三是向近海拓展，包括游艇和海洋牧场。海洋牧场的能源中枢控制目前还是空白，比电科技通过“AI视觉预警+三电底层”的水上生命底盘，以及深远海“AI微电网大脑”，打造“零事故、零排放”的智慧系统。\n投资方观点：\n金桥基金表示：\n我们长期看好船舶与航运产业的绿色升级方向，比电科技在其所处的产业位置与能力结构具备明显稀缺性，公司具备真正的“全船能源系统”级别能力，而非简单设备集成；另一方面，比电已完成从小型船舶到2000吨级运输船的跨船型交付验证，证明其技术不仅成立，更具备规模化复制的工程基础；最后，公司已成功取得过亿订单，给后续发展打造了坚实基础，体现了比电科技在行业早期阶段具备难以复制的先发优势。随着船舶电动化与智能化持续发展，比电科技于2026年起，也将在海洋牧场、游艇智驾等多元场景持续拓展应用边界，并依托内河与沿海产业基础，加速向海外市场延伸，面向全球市场提前布局。在此，也祝贺比电科技顺利完成本轮融资，期待公司在新的发展阶段不断突破，共同推动中国船舶电动化迈向更高水平。', NULL, '2026-05-22 15:56:57');
INSERT INTO `news_detail` VALUES (151, 4327, 21, '金融领域', '韩国邮政拟加码AI数据中心和欧美地产投资', '', '韩国邮政（Korea Post）目前管理约157万亿韩元（约合1040亿美元）的储蓄与保险资金，是韩国最重要的长期机构投资者之一。在传统邮政业务持续亏损压力下，韩国邮政正加速转向高收益资产投资，重点布局AI数据中心、物流设施以及多户型住宅等欧美房地产资产，以提升整体投资回报率。韩国邮政已选定黑石和麦迪逊国际地产作为优先竞标者，共同管理一只规模约2.3亿美元的二级市场房地产基金。（财联社）', 'https://36kr.com/newsflashes/3820157288157319?f=rss', 0, '', '{\"summary\": \"本文披露韩国大型机构投资者的投资新方向，可为出海投资相关领域参与者提供市场参考\", \"abstract\": \"韩国邮政是韩国重要的长期机构投资者，当前管理约1040亿美元的储蓄与保险资金。受传统邮政业务持续亏损的压力，韩国邮政正加速调整投资方向转向高收益资产。其本次重点布局AI数据中心、物流设施以及欧美多户型住宅等房地产资产，以提升整体投资回报率。韩国邮政已选定合作机构，共同管理一只规模约2.3亿美元的二级市场房地产基金。\", \"keywords\": [\"韩国邮政\", \"AI数据中心\", \"欧美地产投资\", \"机构投资\", \"房地产基金\", \"高收益资产\"], \"policy_risk\": {\"market_risk\": \"未提及\", \"policy_compliance\": \"未提及\"}, \"topic_cluster\": \"海外市场洞察\", \"industry_category\": \"金融领域\"}', '', '{\"url\": \"https://36kr.com/newsflashes/3820157288157319?f=rss\", \"title\": \"韩国邮政拟加码AI数据中心和欧美地产投资\", \"source\": \"https://36kr.com/feed\", \"content\": \"韩国邮政（Korea Post）目前管理约157万亿韩元（约合1040亿美元）的储蓄与保险资金，是韩国最重要的长期机构投资者之一。在传统邮政业务持续亏损压力下，韩国邮政正加速转向高收益资产投资，重点布局AI数据中心、物流设施以及多户型住宅等欧美房地产资产，以提升整体投资回报率。韩国邮政已选定黑石和麦迪逊国际地产作为优先竞标者，共同管理一只规模约2.3亿美元的二级市场房地产基金。（财联社）\", \"is_policy\": 0, \"origin_msg\": {\"link\": \"https://36kr.com/newsflashes/3820157288157319?f=rss\", \"links\": [{\"rel\": \"alternate\", \"href\": \"https://36kr.com/newsflashes/3820157288157319?f=rss\", \"type\": \"text/html\"}], \"title\": \"韩国邮政拟加码AI数据中心和欧美地产投资\", \"source\": {\"title\": \"36氪\"}, \"summary\": \"韩国邮政（Korea Post）目前管理约157万亿韩元（约合1040亿美元）的储蓄与保险资金，是韩国最重要的长期机构投资者之一。在传统邮政业务持续亏损压力下，韩国邮政正加速转向高收益资产投资，重点布局AI数据中心、物流设施以及多户型住宅等欧美房地产资产，以提升整体投资回报率。韩国邮政已选定黑石和麦迪逊国际地产作为优先竞标者，共同管理一只规模约2.3亿美元的二级市场房地产基金。（财联社）\", \"published\": \"2026-05-22 15:44:56  +0800\", \"title_detail\": {\"base\": \"https://36kr.com/feed\", \"type\": \"text/plain\", \"value\": \"韩国邮政拟加码AI数据中心和欧美地产投资\", \"language\": null}, \"summary_detail\": {\"base\": \"https://36kr.com/feed\", \"type\": \"text/html\", \"value\": \"韩国邮政（Korea Post）目前管理约157万亿韩元（约合1040亿美元）的储蓄与保险资金，是韩国最重要的长期机构投资者之一。在传统邮政业务持续亏损压力下，韩国邮政正加速转向高收益资产投资，重点布局AI数据中心、物流设施以及多户型住宅等欧美房地产资产，以提升整体投资回报率。韩国邮政已选定黑石和麦迪逊国际地产作为优先竞标者，共同管理一只规模约2.3亿美元的二级市场房地产基金。（财联社）\", \"language\": null}, \"published_parsed\": [2026, 5, 22, 7, 44, 56, 4, 142, 0]}, \"published_at\": \"2026-05-22 15:44:56\", \"ai_json_output\": \"\"}', '账号设置\n我的关注\n我的收藏\n申请的报道\n退出登录\n登录\n搜索\n36氪Auto\n数字时氪\n未来消费\n智能涌现\n未来城市\n启动Power on\n36氪出海\n36氪研究院\n潮生TIDE\n36氪企服点评\n36氪财经\n职场bonus\n36碳\n后浪研究所\n暗涌Waves\n硬氪\n氪睿研究院\n媒体品牌\n企业号\n企服点评\n36Kr研究院\n36Kr创新咨询\n企业服务\n核心服务\n城市之窗\n政府服务\n创投发布\nLP源计划\nVClub\nVClub投资机构库\n投资机构职位推介\n投资人认证\n投资人服务\n寻求报道\n36氪Pro\n创投氪堂\n企业入驻\n创业者服务\n创投平台\nAI测评网\n首页\n快讯\n资讯\n推荐\n财经\nAI\n自助报道\n城市\n最新\n创投\n汽车\n科技\n专精特新\n直播\n视频\n专题\n活动\n搜索\n寻求报道\n我要入驻\n城市合作\n05\n月\n22\n韩国邮政拟加码AI数据中心和欧美地产投资\n2026-05-22 15:44\n分享至\n打开微信“扫一扫”，打开网页后点击屏幕右上角分享按钮\n韩国邮政（Korea Post）目前管理约157万亿韩元（约合1040亿美元）的储蓄与保险资金，是韩国最重要的长期机构投资者之一。在传统邮政业务持续亏损压力下，韩国邮政正加速转向高收益资产投资，重点布局AI数据中心、物流设施以及多户型住宅等欧美房地产资产，以提升整体投资回报率。韩国邮政已选定黑石和麦迪逊国际地产作为优先竞标者，共同管理一只规模约2.3亿美元的二级市场房地产基金。（财联社）\n原文链接\n下一篇\n智元西南具身智能产业基地首批200台机器人正式下线\n36氪获悉，据成都发布，5月22日，智元西南具身智能产业基地、1+N分布式数据采集及训练场在郫都高新区正式启用，现场首批成都造新一代人形机器人远征A3、A2、灵犀X2等200台机器人正式下线。\n15分钟前\n24小时热榜\n查看更多榜单\n8点1氪丨“拉勾网”被曝主动申请破产；特斯拉Model S和X正式停产退役；三星内存工人，奖金或达280万元\n彻底疯狂：韩国全民笑巴菲特无勇，华尔街少智\nFSD监督版入华又进一步，但马斯克还在乎吗？\n22小时前\n那些嘲笑“碳水脸”的人，还是吃太饱了\n7小时前\n断供OpenAI，Anthropic买下全球1/4开发者都在用的工具商\n20小时前\n内娱最严厉的阿嬷来了\n18小时前\n史上首次，Anthropic要赚钱了\n4小时前\n1日暴跌83%，南下资金成最惨“接刀侠”\n18小时前\n关于36氪\n城市合作\n寻求报道\n我要入驻\n投资者关系\n商务合作\n关于我们\n联系我们\n加入我们\n36氪欧洲站\n36氪欧洲站\n36氪欧洲站\nAi产品日报\n网络谣言信息举报入口\n热门推荐\n热门资讯\n热门产品\n文章标签\n快讯标签\n合作伙伴\n36氪APP下载\niOS & Android\n本站由\n阿里云\n提供计算与安全服务 违法和不良信息、未成年人保护举报电话：010-89650707 举报邮箱：jubao@36kr.com\n网上有害信息举报\n© 2011~\n2026\n北京多氪信息科技有限公司 |\n京ICP备12031756号-6\n|\n京ICP证150143号\n|\n京公网安备11010502057322号\n意见反馈\n36氪APP\n让一部分人先看到未来\n36氪\n鲸准\n氪空间\n推送和解读前沿、有料的科技创投资讯\n一级市场金融信息和系统服务提供商\n聚焦全球优秀创业者，项目融资率接近97%，领跑行业', NULL, '2026-05-22 15:57:15');
INSERT INTO `news_detail` VALUES (152, 4358, 7, '消费与零售', 'Finnish phone-maker HMD bundles Indian AI chatbot onto new smartphone in push to reach local market', '', 'HMD is pre-loading Sarvam\'s Indus chatbot app, which supports 22 Indic languages', 'https://techcrunch.com/2026/05/21/finnish-phone-maker-hmd-bundles-indian-ai-chatbot-onto-new-smartphone-in-push-to-reach-local-market/', 0, '', '{\"summary\": \"本文介绍HMD出海印度的本地化布局动作，为出海印度的消费电子企业提供市场参考\", \"abstract\": \"芬兰手机厂商HMD为拓展印度本土市场，推出了预装印度本土AI聊天机器人的新款智能手机。这款名为Indus的AI聊天机器人由Sarvam开发，支持22种印度本土语言。该举措是HMD适配印度用户需求、推进市场本地化的重要布局。\", \"keywords\": [\"智能手机出海\", \"本地化\", \"印度市场\", \"AI聊天机器人\", \"本土适配\"], \"policy_risk\": {\"market_risk\": \"未提及\", \"policy_compliance\": \"未提及\"}, \"topic_cluster\": \"海外市场洞察\", \"industry_category\": \"消费与零售\"}', '', '{\"url\": \"https://techcrunch.com/2026/05/21/finnish-phone-maker-hmd-bundles-indian-ai-chatbot-onto-new-smartphone-in-push-to-reach-local-market/\", \"title\": \"Finnish phone-maker HMD bundles Indian AI chatbot onto new smartphone in push to reach local market\", \"source\": \"https://techcrunch.com/feed/\", \"content\": \"HMD is pre-loading Sarvam\'s Indus chatbot app, which supports 22 Indic languages\", \"is_policy\": 0, \"origin_msg\": {\"id\": \"https://techcrunch.com/?p=3125115\", \"link\": \"https://techcrunch.com/2026/05/21/finnish-phone-maker-hmd-bundles-indian-ai-chatbot-onto-new-smartphone-in-push-to-reach-local-market/\", \"tags\": [{\"term\": \"Gadgets\", \"label\": null, \"scheme\": null}, {\"term\": \"Hardware\", \"label\": null, \"scheme\": null}, {\"term\": \"HMD Global\", \"label\": null, \"scheme\": null}, {\"term\": \"India\", \"label\": null, \"scheme\": null}, {\"term\": \"Sarvam AI\", \"label\": null, \"scheme\": null}, {\"term\": \"smartphone\", \"label\": null, \"scheme\": null}], \"links\": [{\"rel\": \"alternate\", \"href\": \"https://techcrunch.com/2026/05/21/finnish-phone-maker-hmd-bundles-indian-ai-chatbot-onto-new-smartphone-in-push-to-reach-local-market/\", \"type\": \"text/html\"}], \"title\": \"Finnish phone-maker HMD bundles Indian AI chatbot onto new smartphone in push to reach local market\", \"author\": \"Ivan Mehta\", \"authors\": [{\"name\": \"Ivan Mehta\"}], \"summary\": \"HMD is pre-loading Sarvam\'s Indus chatbot app, which supports 22 Indic languages\", \"published\": \"Fri, 22 May 2026 06:41:28 +0000\", \"guidislink\": false, \"title_detail\": {\"base\": \"https://techcrunch.com/feed/\", \"type\": \"text/plain\", \"value\": \"Finnish phone-maker HMD bundles Indian AI chatbot onto new smartphone in push to reach local market\", \"language\": null}, \"author_detail\": {\"name\": \"Ivan Mehta\"}, \"summary_detail\": {\"base\": \"https://techcrunch.com/feed/\", \"type\": \"text/html\", \"value\": \"HMD is pre-loading Sarvam\'s Indus chatbot app, which supports 22 Indic languages\", \"language\": null}, \"published_parsed\": [2026, 5, 22, 6, 41, 28, 4, 142, 0]}, \"published_at\": \"2026-05-22 06:41:28\", \"ai_json_output\": \"\"}', NULL, NULL, '2026-05-22 15:59:40');
INSERT INTO `news_detail` VALUES (153, 4409, 6, '科技与数字服务', 'Show HN: KVBoost – chunk-level KV cache reuse for HuggingFace, 5–48x faster TTFT', '', 'Article URL: <a href=\"https://pythongiant.github.io/KVBoost/\">https://pythongiant.github.io/KVBoost/</a>\n\nComments URL: <a href=\"https://news.ycombinator.com/item?id=48232060\">https://news.ycombinator.com/item?id=48232060</a>\n\nPoints: 18\n\n# Comments: 11', 'https://pythongiant.github.io/KVBoost/', 0, '', '{\"summary\": \"本文分享了一款针对HuggingFace的大模型优化工具KVBoost，可为出海AI相关企业优化推理性能提供参考。\", \"abstract\": \"这是一个发布在Show HN的公开技术项目。项目推出了优化工具KVBoost，实现了块级KV缓存复用功能。该工具可将HuggingFace模型的首次token生成时间（TTFT）提升5到48倍。项目相关信息已公开，可供AI开发者参考使用。\", \"keywords\": [\"KVBoost\", \"KV缓存复用\", \"HuggingFace\", \"TTFT\", \"大模型推理\", \"AI优化\"], \"policy_risk\": {\"market_risk\": \"未提及\", \"policy_compliance\": \"未提及\"}, \"topic_cluster\": \"AI技术研发\", \"industry_category\": \"科技与数字服务\"}', '', '{\"url\": \"https://pythongiant.github.io/KVBoost/\", \"title\": \"Show HN: KVBoost – chunk-level KV cache reuse for HuggingFace, 5–48x faster TTFT\", \"source\": \"https://hnrss.org/frontpage\", \"content\": \"Article URL: <a href=\\\"https://pythongiant.github.io/KVBoost/\\\">https://pythongiant.github.io/KVBoost/</a>\\n\\nComments URL: <a href=\\\"https://news.ycombinator.com/item?id=48232060\\\">https://news.ycombinator.com/item?id=48232060</a>\\n\\nPoints: 18\\n\\n# Comments: 11\", \"is_policy\": 0, \"origin_msg\": {\"id\": \"https://news.ycombinator.com/item?id=48232060\", \"link\": \"https://pythongiant.github.io/KVBoost/\", \"links\": [{\"rel\": \"alternate\", \"href\": \"https://pythongiant.github.io/KVBoost/\", \"type\": \"text/html\"}], \"title\": \"Show HN: KVBoost – chunk-level KV cache reuse for HuggingFace, 5–48x faster TTFT\", \"author\": \"pythongiant\", \"authors\": [{\"name\": \"pythongiant\"}], \"summary\": \"<p>Article URL: <a href=\\\"https://pythongiant.github.io/KVBoost/\\\">https://pythongiant.github.io/KVBoost/</a></p>\\n<p>Comments URL: <a href=\\\"https://news.ycombinator.com/item?id=48232060\\\">https://news.ycombinator.com/item?id=48232060</a></p>\\n<p>Points: 18</p>\\n<p># Comments: 11</p>\", \"comments\": \"https://news.ycombinator.com/item?id=48232060\", \"published\": \"Fri, 22 May 2026 04:47:48 +0000\", \"guidislink\": false, \"title_detail\": {\"base\": \"https://hnrss.org/frontpage\", \"type\": \"text/plain\", \"value\": \"Show HN: KVBoost – chunk-level KV cache reuse for HuggingFace, 5–48x faster TTFT\", \"language\": null}, \"author_detail\": {\"name\": \"pythongiant\"}, \"summary_detail\": {\"base\": \"https://hnrss.org/frontpage\", \"type\": \"text/html\", \"value\": \"<p>Article URL: <a href=\\\"https://pythongiant.github.io/KVBoost/\\\">https://pythongiant.github.io/KVBoost/</a></p>\\n<p>Comments URL: <a href=\\\"https://news.ycombinator.com/item?id=48232060\\\">https://news.ycombinator.com/item?id=48232060</a></p>\\n<p>Points: 18</p>\\n<p># Comments: 11</p>\", \"language\": null}, \"published_parsed\": [2026, 5, 22, 4, 47, 48, 4, 142, 0]}, \"published_at\": \"2026-05-22 04:47:48\", \"ai_json_output\": \"\"}', 'pip install kvboost\nKVBoost\nFaster LLM Inference.\nLess VRAM. No Model Changes.\nChunk-level KV cache reuse  ·  FlashAttention-2  ·  AWQ layer streaming  ·  CPU paged decoding', NULL, '2026-05-22 16:00:55');
INSERT INTO `news_detail` VALUES (154, 4391, 6, '科技与数字服务', 'Hark raises $700M Series A for its secretive ‘universal’ AI interface', '', 'Hark expects to release its first multimodal models this summer, which it says will power a personal AI platform that works with existing products and services. The company expects to follow that with hardware devices built specifically for those systems.', 'https://techcrunch.com/2026/05/21/hark-raises-700m-series-a-for-its-secretive-universal-ai-interface/', 0, '', '{\"summary\": \"本文披露海外AI创业公司Hark的融资与产品推出计划，为全球AI赛道出海布局提供参考\", \"abstract\": \"海外AI创业公司Hark完成7亿美元A轮融资，正在研发保密的“通用型”AI界面。该公司计划今年夏天推出首款多模态模型，用于搭建可对接现有产品服务的个人AI平台。后续Hark还将推出专为该AI系统定制的硬件设备。\", \"keywords\": [\"A轮融资\", \"通用AI界面\", \"多模态模型\", \"人工智能\", \"AI硬件\", \"个人AI平台\"], \"policy_risk\": {\"market_risk\": \"未提及\", \"policy_compliance\": \"未提及\"}, \"topic_cluster\": \"海外市场洞察\", \"industry_category\": \"科技与数字服务\"}', '', '{\"url\": \"https://techcrunch.com/2026/05/21/hark-raises-700m-series-a-for-its-secretive-universal-ai-interface/\", \"title\": \"Hark raises $700M Series A for its secretive ‘universal’ AI interface\", \"source\": \"https://techcrunch.com/feed/\", \"content\": \"Hark expects to release its first multimodal models this summer, which it says will power a personal AI platform that works with existing products and services. The company expects to follow that with hardware devices built specifically for those systems.\", \"is_policy\": 0, \"origin_msg\": {\"id\": \"https://techcrunch.com/?p=3124559\", \"link\": \"https://techcrunch.com/2026/05/21/hark-raises-700m-series-a-for-its-secretive-universal-ai-interface/\", \"tags\": [{\"term\": \"AI\", \"label\": null, \"scheme\": null}, {\"term\": \"Fundraising\", \"label\": null, \"scheme\": null}, {\"term\": \"AI assistants\", \"label\": null, \"scheme\": null}, {\"term\": \"AI hardware\", \"label\": null, \"scheme\": null}, {\"term\": \"hark\", \"label\": null, \"scheme\": null}], \"links\": [{\"rel\": \"alternate\", \"href\": \"https://techcrunch.com/2026/05/21/hark-raises-700m-series-a-for-its-secretive-universal-ai-interface/\", \"type\": \"text/html\"}], \"title\": \"Hark raises $700M Series A for its secretive ‘universal’ AI interface\", \"author\": \"Tim Fernholz\", \"authors\": [{\"name\": \"Tim Fernholz\"}], \"summary\": \"Hark expects to release its first multimodal models this summer, which it says will power a personal AI platform that works with existing products and services. The company expects to follow that with hardware devices built specifically for those systems.\", \"published\": \"Thu, 21 May 2026 14:00:00 +0000\", \"guidislink\": false, \"title_detail\": {\"base\": \"https://techcrunch.com/feed/\", \"type\": \"text/plain\", \"value\": \"Hark raises $700M Series A for its secretive ‘universal’ AI interface\", \"language\": null}, \"author_detail\": {\"name\": \"Tim Fernholz\"}, \"summary_detail\": {\"base\": \"https://techcrunch.com/feed/\", \"type\": \"text/html\", \"value\": \"Hark expects to release its first multimodal models this summer, which it says will power a personal AI platform that works with existing products and services. The company expects to follow that with hardware devices built specifically for those systems.\", \"language\": null}, \"published_parsed\": [2026, 5, 21, 14, 0, 0, 3, 141, 0]}, \"published_at\": \"2026-05-21 14:00:00\", \"ai_json_output\": \"\"}', NULL, NULL, '2026-05-22 16:01:19');
INSERT INTO `news_detail` VALUES (155, 4427, 7, '消费与零售', 'Shopify 用 MySQL 替代 Redis 实现库存预留水平扩展：SKIP LOCKED 与复合主键的工程实践', '', '在电商系统中，库存预留是一个看似简单却极其关键的操作。当买家点击\"完成购买\"时，系统必须在极短时间内保证所购商品仍然可用——如果出错，要么两个买家买到同一件最后的库存（商家不得不取消订单、发送道歉邮件并承担客服成本），要么告诉买家有货但实际无货（商家损失一笔本可完成的销售）。 在Shopify的规模下，任何...', 'https://www.oschina.net/news/444315', 0, '', '{\"summary\": \"本文分享Shopify大规模场景下库存预留架构改造实践，为出海跨境电商优化技术架构提供参考\", \"abstract\": \"本文围绕电商系统核心功能库存预留展开，明确了该功能对商家经营的关键意义。指出库存预留操作出错会给商家带来额外客服成本或是直接的销售损失。文章介绍了Shopify在大规模业务下，尝试用MySQL替代Redis实现库存预留水平扩展的工程实践\", \"keywords\": [\"Shopify\", \"库存预留\", \"MySQL\", \"Redis\", \"水平扩展\", \"复合主键\", \"跨境电商\"], \"policy_risk\": {\"market_risk\": \"库存预留操作出错会引发超卖、错卖问题，导致商家增加客服成本、损失销售订单\", \"policy_compliance\": \"未提及\"}, \"topic_cluster\": \"跨境电商技术\", \"industry_category\": \"消费与零售\"}', '', '{\"url\": \"https://www.oschina.net/news/444315\", \"title\": \"Shopify 用 MySQL 替代 Redis 实现库存预留水平扩展：SKIP LOCKED 与复合主键的工程实践\", \"source\": \"https://www.oschina.net/news/rss\", \"content\": \"在电商系统中，库存预留是一个看似简单却极其关键的操作。当买家点击\\\"完成购买\\\"时，系统必须在极短时间内保证所购商品仍然可用——如果出错，要么两个买家买到同一件最后的库存（商家不得不取消订单、发送道歉邮件并承担客服成本），要么告诉买家有货但实际无货（商家损失一笔本可完成的销售）。 在Shopify的规模下，任何...\", \"is_policy\": 0, \"origin_msg\": {\"id\": \"https://www.oschina.net/news/444315\", \"link\": \"https://www.oschina.net/news/444315\", \"tags\": [{\"term\": \"综合新闻\", \"label\": null, \"scheme\": null}], \"links\": [{\"rel\": \"alternate\", \"href\": \"https://www.oschina.net/news/444315\", \"type\": \"text/html\"}], \"title\": \"Shopify 用 MySQL 替代 Redis 实现库存预留水平扩展：SKIP LOCKED 与复合主键的工程实践\", \"summary\": \"在电商系统中，库存预留是一个看似简单却极其关键的操作。当买家点击&quot;完成购买&quot;时，系统必须在极短时间内保证所购商品仍然可用——如果出错，要么两个买家买到同一件最后的库存（商家不得不取消订单、发送道歉邮件并承担客服成本），要么告诉买家有货但实际无货（商家损失一笔本可完成的销售）。 在Shopify的规模下，任何...\", \"published\": \"Fri, 22 May 2026 14:47:12 +0800\", \"guidislink\": false, \"title_detail\": {\"base\": \"https://www.oschina.net/news/rss\", \"type\": \"text/plain\", \"value\": \"Shopify 用 MySQL 替代 Redis 实现库存预留水平扩展：SKIP LOCKED 与复合主键的工程实践\", \"language